(window.MUSEUM_PAINT_T = window.MUSEUM_PAINT_T || {})["id"] = {"ui":{"lead":"Orang tidak hanya memainkan permainan, tetapi juga melukisnya. Perbesar lukisan dan patung dari 3.300 tahun ini dan lihat detailnya.","details":"Detail","links":"Lihat atau mainkan permainannya","record":"Tentang karya","game":"Permainan","exhibit":"Koleksi","room":"Ruang","room_chance":"Peluang","hint":"Cubit atau gulir untuk memperbesar · seret untuk menggeser · ketuk nomor","r_artist":"Seniman","r_date":"Masa","r_place":"Tempat","r_medium":"Bahan dan teknik","r_size":"Ukuran","r_museum":"Museum","r_credit":"Asal perolehan","r_rights":"Gambar","met":"The Metropolitan Museum of Art","cc0":"Akses terbuka (domain publik)","metlink":"Karya ini di situs museum","credit":"Gambar: The Metropolitan Museum of Art, The Cleveland Museum of Art, The Art Institute of Chicago, dan Rijksmuseum, akses terbuka (domain publik).","cma":"The Cleveland Museum of Art","aic":"The Art Institute of Chicago","rijks":"Rijksmuseum, Amsterdam"},"nefertari":{"title":"Ratu Nefertari Bermain Senet","artist":"Nina de Garis Davies (salinan)","date":"asli sekitar 1290–1224 SM · salinan 1921–22","place":"Mesir (Lembah Para Ratu)","game":"Senet","medium":"Tempera di atas kertas (salinan setengah ukuran)","p":["Nefertari adalah permaisuri utama Ramses II. Ini salinan lukisan dari makamnya di Lembah Para Ratu, dibuat di dalam makam itu pada 1921–22; bahkan retakan dan bagian dinding yang hilang ikut disalin.","Sang ratu duduk di depan papan dan bermain senet melawan lawan yang tak terlihat. Dilukis di makam, permainan ini diduga bermakna lebih dari hiburan: memenangkan perjalanan ke alam baka."],"spots":[["Dua jenis bidak","Di papan ada bidak berujung runcing dan bidak berbentuk gulungan benang: satu set untuk tiap pemain."],["Tangan sang ratu","Jarinya hendak mengambil bidak."],["Papan dan penyangga","Papan digambar dari samping, jadi petaknya tidak terlihat. Papan diletakkan di penyangga berkaki ramping."],["Namanya","Nama sang ratu tertulis di dalam bingkai oval, kartus."],["Lawan yang tak terlihat","Tak ada siapa pun di seberangnya: sang ratu bermain melawan lawan yang tak tampak."]]},"hydria":{"title":"Akhilleus dan Aias Bermain Permainan Papan (guci air)","artist":"Dikaitkan dengan Kelompok Leagros","date":"sekitar 510 SM","place":"Yunani (Attika)","game":"Permainan dadu","medium":"Terakota (figur hitam)","p":["Saat pengepungan Troya, dua pahlawan Yunani, Akhilleus dan Aias, mengisi waktu di depan papan. Adegan ini diciptakan sekitar 540 SM oleh pembuat tembikar dan pelukis Eksekias; aslinya tersimpan pada amfora di Museum Vatikan.","Tema ini sangat digemari antara sekitar 540 dan 480 SM, dan lebih dari 150 contoh diketahui. Pada guci ini, dewi Athena berdiri di tengah. Kedua pahlawan memainkan permainan yang bidaknya maju menurut lemparan dadu."],"spots":[["Athena","Dewi Athena berdiri di antara keduanya."],["Pahlawan di kiri","Masih memegang tombak, ia membungkuk ke papan."],["Pahlawan di kanan","Ia juga tak meletakkan senjatanya: sejenak bermain di tengah perang."],["Papan","Balok rendah di antara mereka adalah papannya."],["Bahu guci","Di bahu guci, sebuah kereta perang berangkat."]]},"liubo":{"title":"Sepasang Figur Duduk Bermain Liubo","date":"abad ke-1 SM – abad ke-1 M","place":"Tiongkok (dinasti Han)","game":"Liubo","medium":"Gerabah berwarna","p":["Dua pemain liubo, permainan yang sangat digemari di Tiongkok zaman Han. Figur seperti ini diletakkan di makam dengan harapan kesenangan hidup terus berlanjut setelah kematian.","Di foto, papan liubo dan bidak tulang dari koleksi museum ini diletakkan di antara mereka. Figur ini menangkap saat dramatis dalam permainan yang memanas."],"spots":[["Papan liubo","Papan yang sama dengan “Papan dan Bidak Liubo” di koleksi: lihat tanda T, L, dan V."],["Pemain di kiri","Ia mengamati papan dengan tenang."],["Pemain di kanan","Tangan terangkat, mulut terbuka lebar: apakah ia baru membuat langkah kemenangan?"],["Bidak di papan","Bidak tulang berdiri di kedua ujung papan."],["Bidak di luar papan","Ada pula bidak di lantai."]]},"shahnama":{"title":"“Buzurjmihr Memecahkan Permainan Catur dari India”, dari Shahnama Shah Tahmasp","artist":"Lukisan dikaitkan dengan ʿAbd al-Vahhab","date":"sekitar 1530–35","place":"Iran (Tabriz)","game":"Catur","medium":"Cat air opak, tinta, perak, dan emas di atas kertas","p":["Adegan dari epos Ferdowsi, Shahnama (Kitab Para Raja). Raja India mengirim utusan membawa papan dan bidak catur dan menantang raja Persia Nushirvan: jika ia bisa menemukan cara memainkannya, India akan membayar upeti.","Hanya bijak muda Buzurjmihr yang memecahkannya tepat waktu. Dalam Shahnama, Persia lalu mengirim backgammon sebagai balasan, dan orang India tak mampu memecahkannya. Raja dan para bangsawan menatap lekat papan dan para pemain."],"spots":[["Papan catur","Bidak berdiri di papan berkotak-kotak, begitu kecil hingga bentuknya sulit dikenali."],["Raja Nushirvan","Di singgasananya, ia menunggu teka-teki terpecahkan."],["Di sekeliling papan","Para pemain membungkuk ke papan."],["Bait-bait syair","Bingkai atas dan bawah memuat syair Ferdowsi."],["Para bangsawan","Orang-orang bersorban dengan tongkat merah tinggi menonton sambil berdiri."]]},"chaupar":{"title":"Siwa dan Parwati Bermain Chaupar, dari seri Rasamanjari","artist":"Devidasa dari Nurpur","date":"1694–95","place":"India (Basohli, Jammu)","game":"Chaupar (kerabat leluhur Ludo)","medium":"Cat air opak, tinta, perak, dan emas di atas kertas","p":["Satu halaman dari seri yang menggambarkan Rasamanjari, puisi cinta Sanskerta abad ke-15. Dewa Siwa dan istrinya Parwati duduk di atas kulit harimau mengelilingi papan berbentuk salib.","Siwa baru saja mengambil kalung Parwati dengan curang, dan Parwati memohon kepadanya. Warna berani, kedalaman ruang yang samar, serta warna dan gerak tubuh yang bermakna: itulah ciri aliran Basohli."],"spots":[["Papan berbentuk salib","Chaupar dan pachisi dimainkan di papan berbentuk salib seperti ini."],["Batang putih di papan","Kemungkinan dadu panjang (pasa) untuk chaupar."],["Siwa","Bertubuh putih, dengan ular di leher."],["Parwati","Dengan tangan terulur, ia meminta kalungnya kembali."],["Kulit harimau","Keduanya duduk di atas kulit harimau."]]},"shogi":{"title":"Wanita dan Pria Muda Bermain Shōgi (“Chūnagon Kanesuke”, dari Tiga Puluh Enam Penyair Abadi)","artist":"Suzuki Harunobu","date":"sekitar 1767–69","place":"Jepang (Edo)","game":"Shogi","medium":"Cetak cukil kayu (nishiki-e)","p":["Cetakan dari seri yang mengacu pada Tiga Puluh Enam Penyair Abadi; yang ini mewakili penyair Chūnagon Kanesuke. Pada malam musim panas, di samping kelambu, seorang wanita dan pria muda bermain shogi.","Harunobu adalah seniman yang mempopulerkan cetakan berwarna penuh, dicetak dengan banyak papan. Bahkan bidak di papan digambar dengan rinci."],"spots":[["Papan shogi berkaki","Papan tebal berkaki, seperti sekarang."],["Kotak kecil","Kemungkinan kotak tempat bidak."],["Kelambu","Kelambu hijau tergantung: ini malam musim panas."],["Lentera","Lampu berdiri menerangi papan."],["Puisi","Bingkai berbentuk awan memuat nama penyair dan sebuah puisi."]]},"sugoroku":{"title":"Dua Wanita Muda Bermain Sugoroku","artist":"Utagawa Toyokuni I","date":"zaman Edo (akhir abad ke-18 – awal abad ke-19)","place":"Jepang (Edo)","game":"Ban-sugoroku (kerabat backgammon)","medium":"Diptik cetak cukil kayu","p":["Dua cetakan disatukan menjadi gambar lebar: para wanita muda di sebuah ruangan menikmati permainan ban-sugoroku. Permainan ini kerabat backgammon, satu garis dengan papan sugoroku Shōsōin di koleksi ini.","Di papan ada batu putih dan hitam, dan wanita muda di kanan memegang wadah untuk mengocok dadu. Gunung Fuji terlihat dari jendela."],"spots":[["Papan","Batu putih dan hitam di petak-petaknya yang panjang."],["Wadah dadu","Dadu dikocok di dalamnya."],["Batu di luar papan","Sudah dikeluarkan, atau belum masuk?"],["Gunung Fuji","Fuji di balik jendela."],["Sambungan","Di sini dua cetakan bertemu."]]},"eakins":{"title":"Para Pemain Catur","artist":"Thomas Eakins","date":"1876","place":"Amerika Serikat (Philadelphia)","game":"Catur","medium":"Cat minyak di atas kayu","p":["Di ruang tamu sebuah rumah di Philadelphia, dua sahabat bermain catur sementara ayah sang seniman, Benjamin Eakins, menonton. Eakins belajar menyusun ruang dengan cermat dan detail yang tepat dari gurunya di Paris, Gérôme.","Pada 1881, Para Pemain Catur menjadi karya pertama yang diterima Metropolitan Museum sebagai hadiah dari seniman yang masih hidup."],"spots":[["Bidak catur","Di ruangan yang remang, bidak di papan tampak terang tersinari."],["Ayah sang seniman","Berdiri menyaksikan permainan: Benjamin Eakins."],["Pemain di kanan","Pelukis George W. Holmes, sahabat ayah sang seniman."],["Laci meja","Tulisan Latin: “Putra Benjamin Eakins melukis ini pada ’76.”"],["Di atas perapian","Reproduksi lukisan Gérôme, guru Eakins."],["Kucing","Di lantai, hanya kucing yang tampak tak peduli pada permainan."]]},"weiqi":{"title":"Piring dengan dewa abadi bermain weiqi","artist":"Tidak diketahui","date":"1425–36 (Dinasti Ming, masa Xuande)","place":"Tiongkok","game":"Go (weiqi)","medium":"Lak ukir merah dan hijau","size":"T. 3,5; L. 14,9; P. 23,5 cm","credit":"Hibah Florence dan Herbert Irving, 2015","p":["Piring lak ukir: puluhan lapis lak dioleskan lalu diukir; di bawah lapisan merah ada lapisan hijau, sehingga kedalaman ukiran memunculkan warnanya. Di dalam tepi yang berlekuk, para dewa abadi bermain go di bawah pohon pinus.","Tiongkok punya legenda Lanke, “gagang kapak yang lapuk”: penebang kayu Wang Zhi menonton dewa abadi bermain go di gunung, dan saat tersadar, waktu telah berlalu begitu lama hingga gagang kapaknya lapuk. Dewa abadi di depan papan adalah tema yang digemari. Siapa sosok yang berdiri, catatan tidak menyebutkan."],"spots":[["Papan","Papan go di antara dua dewa abadi, diukir sampai ke garis-garisnya."],["Dewa abadi yang bermain","Dua sosok duduk di dekat batu, mengelilingi papan."],["Sosok yang berdiri","Sosok yang berdiri agak jauh. Ia mengingatkan pada penebang kayu dalam legenda, tetapi siapa dia tidak diketahui."],["Bulan","Bulan bulat di langit (atau mungkin matahari)."],["Pinus","Pinus yang dahannya membentang, pohon yang sering melambangkan umur panjang dan negeri dewa."],["Tepi bunga peoni","Bunga peoni besar dan daunnya diukir di sekeliling tepi."]]},"webb":{"title":"Pemain backgammon (lemari)","artist":"Philip Webb (desain), Edward Burne-Jones (lukisan), Morris, Marshall, Faulkner & Co. (pembuat)","date":"1861","place":"Inggris (London)","game":"Backgammon","medium":"Kayu pinus dicat, cat minyak di atas kulit, kuningan, tembaga","size":"T. 185,4; L. 114,3; D. 53,3 cm","credit":"Rogers Fund, 1926","p":["Salah satu perabot paling awal dari perusahaan yang didirikan William Morris bersama teman-temannya pada 1861. Di kulit pintunya dilukis dengan cat minyak seorang pria dan wanita berbusana abad pertengahan yang sedang bermain backgammon. Lemari ini dipamerkan di Pameran Internasional London 1862.","Karya ini merangkum cita-cita gerakan Arts and Crafts untuk menghapus batas antara seni rupa dan seni terapan. Latar kulitnya ditatah titik-titik kecil, teknik abad pertengahan."],"spots":[["Papan","Papan backgammon di meja di antara keduanya."],["Pria","Seorang pemuda memegang bidak, menatap papan."],["Wanita","Di hadapannya, seorang wanita memegang bidak (atau wadah dadu)."],["Bunga di kaki mereka","Bunga tumbuh di kaki para pemain."],["Kulit bertatah","Latar kulit ditatah titik-titik halus yang menangkap cahaya."],["Pita belah ketupat","Pita bermotif belah ketupat di atas emas membingkai pintu di atas dan bawah."]]},"liberale":{"title":"Para Pemain Catur","artist":"Liberale da Verona","date":"sekitar 1475","place":"Italia (Verona)","game":"Catur","medium":"Tempera di atas kayu","size":"34,9 × 41,3 cm","credit":"Koleksi Maitland F. Griggs, wasiat Maitland F. Griggs, 1943","p":["Pecahan bagian depan cassone, peti berhias tempat menyimpan barang bawaan pengantin di Italia masa Renaisans. Liberale juga dikenal karena menghias buku-buku paduan suara Katedral Siena.","Lukisan ini menampilkan satu adegan dari kisah cinta yang tak diketahui judulnya. Pada pecahan pasangannya, seorang gadis di jendela tampak memanggil seorang pemuda masuk; di sini keduanya bermain catur. Menurut museum, si gadis hampir kalah. Catur adalah gambaran favorit tentang merayu dalam sastra cinta masa itu."],"spots":[["Papan catur","Papan merah-putih dengan bidak gelap; permainan tampaknya hampir usai."],["Si pemuda","Ia menjangkau papan dan tampaknya akan menang."],["Si gadis","Duduk di seberang; di panel pasangannya ia memanggil si pemuda dari jendela."],["Jendela","Di balik jendela yang terbuka tampak bukit dan langit."],["Para pemuda yang menonton","Para pria bersedekap mengikuti permainan."],["Para gadis yang menonton","Para gadis mengintip permainan dari balik tiang."]]},"mirror":{"title":"Wadah cermin dengan pasangan bermain catur","artist":"Tidak diketahui","date":"1325–50","place":"Prancis (Paris)","game":"Catur","medium":"Gading","size":"Diameter 10,2 cm","credit":"Dibeli dengan Dana J. H. Wade, 1940","p":["Cakram gading seukuran telapak tangan ini dulu menutupi sebuah cermin tangan. Di Paris abad ke-14, cermin logam yang digosok mengilap diapit dua lempeng gading lalu dibawa ke mana-mana; ukiran gading seperti ini adalah barang mewah kesukaan kalangan istana dan bangsawan.","Di dalam tenda bertirai, seorang pemuda dan seorang wanita bangsawan bermain catur. Dalam kisah-kisah abad pertengahan, catur melambangkan cinta sekaligus perang. Ada yang menduga pasangan ini Tristan dan Isolde, atau Lancelot dan Guinevere, tetapi tak ada yang tahu pasti. Museum bertanya kepada pengunjungnya: menurutmu siapa yang sedang menang?"],"spots":[["Papan catur","Papan di atas meja berkaki satu, dengan beberapa bidak."],["Si pemuda","Ia menjulurkan tangan untuk melangkah."],["Si wanita","Wanita berkerudung; ujung jarinya menyentuh sebuah bidak."],["Tangan yang terkepal","Tangannya yang lain terkepal di pangkuan. Apakah ia menggenggam bidak yang ditangkapnya?"],["Tenda","Tirai yang diikat di kedua sisi — latar yang sering muncul pada adegan catur di wadah cermin."]]},"morris":{"title":"Sebuah papan permainan (Nine Men’s Morris)","artist":"Peter Flötner","date":"1500–46","place":"Jerman","game":"Nine Men’s Morris","medium":"Cukil kayu","credit":"Dana Abadi Charles W. Harkness, 1923","p":["Cetakan cukil kayu karya Peter Flötner, salah satu pematung paling berbakat di Nürnberg masa Renaisans, yang juga merancang ornamen, perabot, model untuk pandai emas, dan satu set kartu remi yang terkenal karena sindirannya. Di balik sulur daun yang berpilin tersembunyi papan Nine Men’s Morris — “Mühle” dalam bahasa Jerman: tiga persegi bersarang yang dihubungkan di tengah setiap sisi.","Papan ini punya 24 titik. Siapa yang menjajarkan tiga bidaknya (sebuah “gilingan”) boleh mengambil satu bidak lawan. Cetakan seperti ini juga menjadi contoh bagi para perajin, dan museum memamerkan lembaran ini dalam pameran model dan rancangan pandai emas. Tidak tercatat apakah orang bermain langsung di atas kertasnya, atau menyalinnya ke kayu atau logam."],"spots":[["Persegi tengah","Persegi paling dalam, penuh anyaman halus."],["Sudut luar","Sudut persegi luar — salah satu dari 24 titik tempat bidak berdiri."],["Sudut tengah","Sudut persegi tengah juga merupakan titik."],["Garis penghubung","Pita yang menghubungkan ketiga persegi di tengah setiap sisi; bidak juga bergerak di atasnya."],["Topeng","Kartus berpilin dan wajah di atas, bawah, dan samping — ornamen grotesk Renaisans."],["Bingkai sulur anggur","Daun dan buah yang dicukil putih di atas dasar hitam."]]},"leifeng":{"title":"Papan permainan Pagoda Leifeng","artist":"Tidak diketahui","date":"1736–95 (masa Qianlong)","place":"Tiongkok","game":"Permainan balapan","medium":"Cukil kayu; tinta di atas kertas","size":"31 × 29,8 cm","credit":"Dibeli dengan Dana J. H. Wade, 2025","p":["Selembar cetakan untuk dimainkan, dari masa pemerintahan Kaisar Qianlong di Tiongkok era Qing. Petak-petaknya dihuni tokoh-tokoh Legenda Ular Putih: roh ular Bai Suzhen (“Nyonya Putih”), kawannya Xiaoqing (“Si Hijau Kecil”), pemuda Xu Xuan (Xu Xian dalam versi-versi kemudian), dan biksu Fahai, yang akhirnya mengurung Nyonya Putih di bawah Pagoda Leifeng di tepi Danau Barat.","Lintasannya berpilin dari petak bertuliskan 起馬, “berangkat”, menuju pagoda di tengah. Para pemain mungkin berlomba menyusuri kisahnya dengan dadu, seperti Permainan Angsa di Barat; aturannya tidak tercatat. Menurut museum, cetakan berwarna seperti ini dijual di kota-kota dan digantung di dinding sebagai bagian budaya visual perkotaan — setiap warna dicetak dari papan ukir tersendiri."],"spots":[["Mulai","Petak bertuliskan 起馬, “berangkat” — kemungkinan titik awal."],["Nyonya Putih dan Si Hijau Kecil","Roh ular Bai Suzhen dan kawannya Xiaoqing."],["Xu Xuan","Pemuda yang menikahi Nyonya Putih."],["Biksu Fahai","Biksu yang mengurungnya di bawah pagoda."],["Pagoda Leifeng","Pagoda di tepi Danau Barat, Hangzhou, tempat kisahnya berakhir."],["Tengah","Seorang wanita duduk di depan pagoda dan seorang pria berlutut — adegan terakhir kisah ini, dan mungkin garis akhirnya."]]},"tutinama":{"title":"Monyet yang terluka menggigit tangan pangeran, kawan caturnya (dari Tuti-nama, Kisah-Kisah Burung Nuri)","artist":"Dasavanta","date":"sekitar 1560","place":"India (istana Mughal Akbar)","game":"Catur","medium":"Tempera, tinta, dan emas di atas kertas","size":"20 × 14,2 cm (lukisan 10,2 × 10,6 cm)","credit":"Hadiah Ny. A. Dean Perry, 1962","p":["Ilustrasi dari Tuti-nama, “Kisah-Kisah Burung Nuri”, yang dibuat di istana Kaisar Mughal Akbar. Ini salah satu cerita yang dituturkan induk nuri kepada anak-anaknya agar mereka tidak bersahabat dengan jenis makhluk lain, seperti anak-anak rubah. Dalam cerita itu, seekor monyet yang pandai bermain catur sering bermain dengan seorang pangeran.","Suatu hari, di depan para tamu, si monyet melontarkan lelucon kasar; pangeran menamparnya, dan monyet itu menggigit tangan pangeran. Di luar sebelah kanan, para pelayan menyiapkan makanan sementara para tamu menonton dengan tercengang. Tulisan di bawah menyebut nama Dasavanta, yang kelak menjadi salah satu empu paling termasyhur di istana Mughal; semasa muda ia melapisi bagian bawah lukisannya dengan warna biru yang sejuk."],"spots":[["Si monyet","Menggigit tangan pangeran, kawan caturnya."],["Sang pangeran","Pangeran yang tangannya digigit."],["Papan catur","Papan berpetak merah di lantai."],["Para tamu yang tercengang","Para tamu yang diundang."],["Menyiapkan makanan","Di luar, pelayan menaruh periuk di atas api."],["Teks Persia","Di atas, kisahnya ditulis dalam bahasa Persia."]]},"teniers":{"title":"Permainan backgammon","artist":"David Teniers","date":"1640-an","place":"Flandria","game":"Backgammon","medium":"Cat minyak di atas kayu, dipindahkan ke kanvas","size":"59 × 80,6 cm","credit":"Hadiah Tn. dan Ny. Samuel D. Wise, 1943","p":["Pertandingan backgammon bertaruhan besar karya pelukis Flandria, Teniers. Permainan ini sangat tua: bentuk modernnya muncul pada 1400-an, dan nama “backgammon” lahir kira-kira pada masa lukisan ini dibuat. Pada 1600-an ia sangat populer dan sering dimainkan dengan taruhan uang.","Para penonton mengerumuni kedua pemain, dan di dekat dinding seseorang mencatat skor. Dari para perempuan yang menonton — salah satunya menjulurkan kepala dari jendela — museum menduga ruangan ini adalah ruang judi di sebuah rumah bordil. Adegan permainan seperti ini kerap membawa pesan moral: berjudi itu bodoh, bahkan jahat, dan membuang waktu."],"spots":[["Papan","Papan backgammon yang terbuka di atas meja; permainan sedang berlangsung."],["Pria berbaju putih","Pemain yang membelakangi kita, menjangkau bidaknya."],["Pria bertopang dagu","Lawannya, termenung."],["Pencatat skor","Seorang pria menandai papan di dinding — skor, atau taruhan?"],["Perempuan di jendela","Seorang perempuan tua menonton dari atas."],["Ruang belakang","Di belakang, para pria minum di dekat seorang perempuan muda."]]},"imari":{"title":"Piring dengan dua pria bermain go","artist":"Tidak diketahui","date":"abad ke-18","place":"Jepang (zaman Edo)","game":"Go","medium":"Porselen cetak dengan lukisan email di atas glasir (Hizen, gaya Imari)","size":"2,4 × 13,8 cm","credit":"Koleksi Severance dan Greta Millikin, 1964","p":["Di piring persegi kecil ini, dua pria bermain go di bawah pohon pinus: yang berbaju kuning duduk menghadap papan yang diletakkan langsung di tanah, sementara lawannya yang berbaju hijau bersandar ke pohon.","Ini porselen Imari dari Hizen (kini Saga dan Nagasaki), dan warna hijaunya mengingatkan pada email Kutani. Piring ini dibuat untuk ekspor, ketika Jepang telah menggantikan Tiongkok sebagai pemasok utama porselen ke Eropa."],"spots":[["Papan go","Papan bergaris yang diletakkan langsung di tanah."],["Pria berbaju kuning","Duduk menghadap papan."],["Pria berbaju hijau","Lawannya, bersandar ke pohon sambil tersenyum."],["Pohon pinus","Pinus yang menjulurkan dahannya di atas mereka."],["Bingkai merah","Bingkai merah bersudut potong mengelilingi adegan."]]},"shoei":{"title":"Empat Keterampilan (satu dari sepasang layar lipat)","artist":"dikaitkan dengan Kanō Shōei","date":"akhir abad ke-16–awal abad ke-17","place":"Jepang (zaman Momoyama)","game":"Go","medium":"Satu dari sepasang layar lipat enam panel; tinta dan sedikit warna di atas kertas","size":"153 × 358,6 cm","credit":"Dana John L. Severance, 1979","p":["Layar lipat enam panel yang dikaitkan dengan Kanō Shōei dari aliran Kanō. Bersama pasangannya, layar ini menggambarkan “empat keterampilan” yang diharapkan dari seorang pria terpelajar Tiongkok: memainkan qin, bermain qi (go), kaligrafi, dan melukis. Di sini para pria Tiongkok terpandang beserta pelayan mereka bersantai di padang di bawah pohon pinus.","Di tengah, dua orang bermain go sementara orang ketiga menonton. Di dekatnya, sebuah meja memuat buku dan qin yang masih di dalam sarung kainnya, menunggu dimainkan. Adegan ini menyeimbangkan kesenangan dan tata krama. Museum mencatat bahwa salah satu pelayan teralihkan perhatiannya oleh gerak ikan di air."],"spots":[["Papan go","Papan berkaki; dua pria bermain berhadapan."],["Para pria","Dua pemain dan orang ketiga yang menonton."],["Meja","Kemungkinan meja berisi buku dan qin dalam sarungnya."],["Para pelayan","Pelayan yang menunggu di dekat meja."],["Pelayan yang teralihkan","Berbaring di tepi air, memperhatikan ikan."],["Pinus","Pinus besar membentangkan dahannya di atas adegan."]]},"umaya":{"title":"Sekat Lipat Istal Kuda (go dan shogi di beranda)","artist":"Tidak diketahui","date":"Awal abad ke-16","place":"Jepang (zaman Muromachi)","game":"Go dan shogi","medium":"Satu dari sepasang sekat lipat enam panel; tinta, warna, dan emas di atas kertas","size":"146,1 × 346,6 cm","credit":"Edward L. Whittemore Fund, 1934","p":["Sekat lipat dari enam panel yang disambung ini adalah satu dari sepasang. Kuda-kuda berharga di kandangnya mungkin tema utamanya, tetapi banyak hal terjadi di beranda depan.","Di sana orang-orang saling menantang dalam dua permainan berbeda: go di kiri dan shogi di kanan. Menurut museum, suasana yang hidup muncul dari perpaduan kuda yang gelisah dan strategi tenang permainan. Di Jepang monyet dianggap melindungi kuda, dan kadang dipelihara di istal."],"spots":[["Papan go","Papan bergaris halus dengan batu hitam."],["Dua pria bertopi hitam","Pria bertopi eboshi hitam tinggi: yang berbaju hijau menjangkau papan, yang berbaju merah menonton."],["Papan shogi","Petaknya besar — jauh lebih sedikit daripada papan go."],["Lawan yang tertawa","Seorang biksu berkepala gundul mengambil bidak, sementara pria di depannya memegang kepala sambil tertawa keras. Apakah seseorang baru mencetak angka?"],["Seekor monyet","Di ujung beranda — monyet berbaju merah?"],["Seekor kuda","Kuda hitam mengangkat kaki depannya, ditahan tali."]]},"goryeo":{"title":"Kendi seladon bertatah dengan pemain go","artist":"Tidak diketahui","date":"Abad ke-13","place":"Korea (Dinasti Goryeo)","game":"Go (baduk)","medium":"Seladon dengan tatahan slip putih dan hitam","size":"Tinggi 20,4 cm, diameter 14,3 cm","credit":"Hibah John L. Severance, 1917","p":["Kendi seladon Goryeo dengan cerat dan pegangan. Teknik tatahan — menggores garis pada tanah liat, mengisinya dengan slip putih dan hitam, lalu mengglasir dan membakarnya — adalah keahlian khas perajin Goryeo; di sini, di dalam bingkai bundar, dua sosok yang duduk di bawah pohon dedalu tampak putih.","Di antara mereka ada papan, dan museum membandingkan adegan ini dengan gambar orang bermain go — baduk dalam bahasa Korea. Bermain kecapi, go, kaligrafi, dan lukisan adalah “empat keahlian” cendekiawan terpelajar, dan pertemuan mereka yang anggun juga menjadi motif kerajinan. Seladon Korea bergambar manusia jarang ditemukan."],"spots":[["Papan","Papan di antara keduanya, berupa kotak putih."],["Sosok di kiri","Duduk menghadap papan."],["Sosok di kanan","Lawannya, duduk di seberang."],["Pohon dedalu","Ranting dedalu menjuntai di atas mereka, digambar dengan slip hitam."],["Bingkai awan","Ulir seperti awan mengelilingi bingkai bundar."],["Retak glasir","Retakan halus pada glasir. Terbentuk saat mendingin karena tanah liat dan glasir menyusut berbeda."]]},"kangra":{"title":"Pasangan bermain chaupar di teras","artist":"Tidak diketahui","date":"sekitar 1790–1800","place":"India (Pahari, mazhab Kangra)","game":"Chaupar","medium":"Gambar dengan sketsa awal oker merah","size":"19,4 × 13,2 cm","credit":"Edward L. Whittemore Fund, 1936","p":["Gambar karya seniman Kangra, di perbukitan Pahari di kaki Himalaya. Sketsa pertama dibuat dengan merah (oker merah), lalu dirapikan dengan hitam. Tanpa warna di atasnya, setiap garis tokoh dan benda dapat diikuti.","Seorang pria dan wanita duduk di teras di kedua sisi papan berbentuk salib, bermain chaupar — permainan balap kuno India di salib yang sama dengan pachisi, dimainkan dengan melempar dadu panjang (pasa). Petak-petaknya belum digambar di papan. Para pelayan melayani pasangan itu."],"spots":[["Papan salib","Papan berbentuk salib di lantai. Petaknya belum digambar."],["Sang wanita","Telapak tangannya terbuka ke atas — hendak melempar dadu?"],["Sang pria","Bersorban dengan hiasan bulu; ia menjangkau papan."],["Pelayan di kiri","Memegang botol kecil dan mengulurkan kain."],["Pelayan di kanan","Memegang alat bergagang panjang dan wadah kecil."],["Sketsa merah","Di sekitar sorban, sketsa merah tampak di bawah garis hitam."]]},"vuillard":{"title":"Permainan Dam (dari Pemandangan dan Interior)","artist":"Édouard Vuillard","date":"1899","place":"Prancis","game":"Dam","medium":"Litografi berwarna (state III/III); dicetak oleh Auguste Clot, diterbitkan oleh Ambroise Vollard","size":"Gambar 33 × 25,7 cm (kertas 38 × 30,8 cm)","credit":"Hibah Hanna Fund, 1951","p":["Ambroise Vollard, pedagang lukisan impresionis, juga penerbit cetakan grafis yang penting. Pada 1895 ia memesan album 12 litografi berwarna dari Pierre Bonnard, lalu menerbitkan banyak album lain, di antaranya Pemandangan dan Interior karya Vuillard yang dicetak oleh master pencetak Auguste Clot.","Bonnard dan Vuillard termasuk kelompok Nabis — “para nabi” dalam bahasa Ibrani — yang mencari seni baru tempat bentuk dan warna sendiri mengungkapkan perasaan, dan gemar melukis kehidupan kota serta keluarga. Di ruangan yang penuh motif, dua pria berhadapan di depan papan dam sementara seorang wanita berdiri menonton. Dalam bahasa Prancis permainan ini disebut “dames”; catatan pensil di kiri bawah berbunyi “partie de dames”, satu permainan dam."],"spots":[["Papan","Papan kotak-kotak kecil dengan bidak yang tersusun."],["Pria di kiri","Pria berjanggut mengulurkan tangan ke atas papan."],["Pria di kanan","Lawannya membungkuk di atas papan di kursi berlengan, setengah tertutup wanita yang berdiri."],["Wanita yang berdiri","Dengan tangan di dagu, ia mengikuti permainan."],["Lampu","Lampu di dekat dinding. Kertas dinding dan pelapis kursi penuh motif."],["Catatan pensil","Di kiri bawah dengan pensil: “partie de dames” — satu permainan dam."]]},"talbot":{"title":"Para Pemain Catur (foto awal)","artist":"Diatribusikan kepada William Henry Fox Talbot","date":"sekitar 1843–47","place":"Inggris","game":"Catur","medium":"Cetak kertas bergaram","size":"19,9 × 15 cm","credit":"Dibeli dengan dana dari Tuan dan Nyonya Everett Kovler","p":["Proses negatif-positif ciptaan Talbot, dengan salinan tak terbatas yang dimungkinkannya, mendominasi fotografi hingga era digital. Eksperimen awalnya menunjukkan minat pada sains sekaligus cita-cita artistik, dan para peneliti memastikan ia memotret pemain catur sepuluh kali atau lebih.","Namun foto ini mungkin bukan karyanya: cetakan ini dan versi lain adegan yang sama tidak bertanda tangan dan memakai kertas berbeda dari biasanya. Yang difoto kemungkinan fotografer Antoine Claudet dan asisten Talbot, Nicolaas Henneman; riset terbaru menduga foto-foto ini dibuat di studio Claudet, berpindah ke Henneman, lalu sampai ke Talbot sebagai bagian pembayaran utang (catatan museum)."],"spots":[["Papan","Papan catur di meja, bidaknya berjajar."],["Pria bertopi tinggi","Dengan topi masih terpasang, ia meraih bidak."],["Pria yang berpikir","Tangan di dagu, lawannya mengamati papan."],["Tirai","Tirai tergantung di belakang — latar untuk pemotretan?"],["Topi lain","Topi tinggi kedua terletak di dudukan sebelah kanan."]]},"pvl":{"title":"Pria Bermain Dadu","artist":"Master PVL","date":"sekitar 1520","place":"Belanda (Negeri-Negeri Rendah)","game":"Dadu","medium":"Grafir di atas kertas","size":"9,4 × 9,4 cm (bundar)","credit":"Koleksi Charles Hack dan Hearn Family Trust, dibeli 2023","p":["Karya seorang pengukir tanpa nama yang aktif di Negeri-Negeri Rendah awal abad ke-16, disebut Master PVL dari monogram “PVL” di kiri bawah. Pada cetakan bundar yang muat di telapak tangan, garis halus yang rapat membangun kedalaman ruangan dan tekstur pakaian.","Di meja ada dua dadu. Seorang pria yang mencondongkan badan dan pemuda berkerah bulu menunjuk dan berdebat — mungkin soal angka. Di belakang, para wanita menonton, dan di bawah meja ada kendi anggur. Dadu sejak zaman kuno terkait dengan judi dan berulang kali dilarang."],"spots":[["Dadu","Dua dadu bergulir di meja."],["Tangan yang menunjuk","Dua jari bertemu di meja — berdebat soal angka?"],["Pria bertopi lebar","Mencondongkan badan; lengan kembung bersayat adalah mode masa itu."],["Pemuda berkerah bulu","Bertopi besar dan berkerah bulu."],["Para wanita yang menonton","Para wanita mengintip permainan dari belakang."],["Monogram","“PVL” di kiri bawah — satu-satunya petunjuk nama senimannya."]]},"kiyohiro":{"title":"Para Pemain Sugoroku","artist":"Torii Kiyohiro","date":"sekitar 1750","place":"Jepang (zaman Edo)","game":"Ban-sugoroku","medium":"Cetak balok kayu berwarna (benizuri-e), ōban; penerbit Urokogataya","size":"43,5 × 29,3 cm","credit":"Koleksi Clarence Buckingham","p":["Torii Kiyohiro adalah seniman ukiyo-e yang aktif sekitar 1737 hingga 1776. Ini adalah benizuri-e, dicetak dengan sedikit balok warna — merah muda beni, hijau, dan sejenisnya — pada tahun-tahun sebelum nishiki-e berwarna penuh muncul pada 1765.","Permainan di atas dudukan hitam adalah ban-sugoroku: dua pemain melempar dadu dan menjalankan bidak putih dan hitam, dan yang pertama mengeluarkan semua bidaknya menang. Permainan ini sekeluarga dengan backgammon, dan cetakan ukiyo-e sering menggambarkan perempuan memainkannya. Di belakang, seorang perempuan mengisap pipa panjang sambil menonton."],"spots":[["Papan","Papan sugoroku di atas dudukannya, dengan bidak putih dan hitam."],["Sosok di kiri","Mengulurkan tangan untuk menjalankan bidak."],["Perempuan di kanan","Membungkuk di atas papan, lawannya mengamati bidak."],["Perempuan berpipa","Dengan pipa kiseru panjang, mengikuti permainan dari belakang."],["Tangan terangkat","Perempuan di kanan mengangkat benda kecil hitam — wadah pengocok dadu?"],["Tanda tangan","“Torii Kiyohiro hitsu” dengan cap penerbit Urokogataya."]]},"ingram":{"title":"Permainan Catur Tiongkok","artist":"John Ingram, menurut François Boucher","date":"1741–63","place":"Prancis (Paris)","game":"Xiangqi","medium":"Etsa dan grafir","size":"Kertas 39,4 × 27,7 cm (pelat 24,5 × 16,4 cm)","credit":"Koleksi Elisha Whittelsey, 1966","p":["Gambar pelukis Prancis François Boucher yang diukir oleh John Ingram kelahiran London. Ingram pindah ke Paris dan, antara 1741 dan 1763, membuat serangkaian cetakan menurut chinoiserie Boucher — Tiongkok seperti yang dibayangkan orang Eropa. Judul di bawahnya berbunyi “LE JEU D'ECHETS CHINOIS”, permainan catur Tiongkok.","Seorang wanita bersanggul tinggi menjalankan bidak di papan di pangkuannya, sementara seorang anak kecil menonton. Permainan ini dianggap xiangqi, padahal bidak xiangqi asli semuanya cakram pipih, sedangkan di sini bidak tinggi berdiri di samping bidak kecil persegi. Pohon palem dan sosok yang duduk di atas guci pun lebih mencerminkan negeri jauh yang diimpikan Eropa kala itu daripada Tiongkok sebenarnya."],"spots":[["Papan dan bidak","Papan di pangkuan, dengan bidak tinggi dan persegi. Bidak xiangqi asli berupa cakram pipih."],["Tangan di bidak","Tangan kanannya menjalankan bidak."],["Bertopang dagu","Tangan kirinya di dagu, ia memandang papan."],["Anak yang menonton","Seorang anak berdiri di dekat papan, mengikuti permainan."],["Sosok di atas guci","Sosok yang duduk bersila di atas guci besar."],["Judul dan nama","“Dessiné par Fr. Boucher”, “Gravé par Ingram” dan judul “LE JEU D'ECHETS CHINOIS”."]]},"posada":{"title":"Permainan Angsa","artist":"José Guadalupe Posada","date":"1909","place":"Meksiko","game":"Permainan angsa","medium":"Cetak timbul dari pelat seng di atas kertas","size":"29,3 × 39,4 cm","credit":"William McCallin McKee Memorial Endowment","p":["Lembar untuk bermain buatan pengukir Meksiko Posada — terkenal dengan tengkorak “calavera”-nya — untuk penerbit Mexico City Antonio Vanegas Arroyo. Pita di kiri bawah bertuliskan “JUEGO DE LA OCA” (permainan angsa), dan lintasannya berpilin dari petak 1 sampai 63 di tengah.","Di tengah tercetak aturannya (EXPLICACION): lemparan pertama 5 dan 4 menuju 26, 6 dan 3 menuju 53. Yang mendarat di angsa (seekor burung) menghitung lagi sebanyak itu; di penginapan (Venta, 19) menunggu dua giliran; di sumur (Poso, 31) dan penjara (Carcel, 52) tinggal sampai pemain lain datang; labirin (42) mengembalikan ke 39, dan maut (Muerte, 58) ke awal. Harus tepat mendarat di 63. Di petak tertentu pemain juga membayar taruhan: ini juga permainan judi."],"spots":[["Aturan","“EXPLICACION” di tengah: efek tiap petak dan kapan membayar taruhan."],["Petak 1","Start. Dari sini lintasan berpilin ke tengah."],["Sumur (31)","Sumur seperti air mancur. Yang jatuh tinggal sampai pemain lain datang."],["Maut (58)","Petak tengkorak: kembali ke awal."],["Pita judul","“JUEGO DE LA OCA” di pita kiri bawah, dengan anak-anak bermain di bawahnya."],["Nama penerbit","Pita sang dewi bertuliskan “IMPRENTA DE A. VANEGAS ARROYO”, penerbit banyak cetakan Posada."]]},"jintile":{"title":"Ubin dengan wanita bermain permainan papan","artist":"Tidak diketahui","date":"Abad ke-13","place":"Tiongkok (Dinasti Jin)","game":"Permainan papan (kemungkinan go)","medium":"Tembikar (relief cetak)","size":"Tinggi 27,3 cm, lebar 24,8 cm, tebal 5,4 cm","credit":"Dibeli dengan sumbangan Friends of Asian Art, 2002","p":["Ubin relief dari masa Jin (1115–1234), dinasti bangsa Jurchen yang menguasai Tiongkok utara. Di bawah pohon berbunga, dua wanita duduk berhadapan di atas panggung dengan papan di antara mereka.","Papannya berpetak halus, jadi kemungkinan mereka bermain go. Wanita di kanan mencondongkan badan dan menunjuk papan, sementara yang di kiri memperhatikan. Banyak makam masa Jin di Tiongkok utara dilapisi bata relief bergambar kehidupan sehari-hari, dan ubin ini kemungkinan menghiasi makam semacam itu."],"spots":[["Papan","Papan berpetak halus, kemungkinan papan go."],["Tangan yang menunjuk","Wanita di kanan menunjuk papan. Langkah berikutnya?"],["Wanita di kiri","Rambut disanggul tinggi, ia memandang papan."],["Wanita di kanan","Mencondongkan badan ke papan."],["Pohon berbunga","Dahan pohon berbunga terbentang di atas mereka."],["Panggung","Panggung tempat mereka duduk, dengan hiasan bergelombang di antara kakinya."]]},"kyosai":{"title":"Kentut Mengacaukan Permainan Go (dari album sketsa)","artist":"Kawanabe Kyōsai","date":"Pertengahan–akhir abad ke-19","place":"Jepang (zaman Edo–Meiji)","game":"Go","medium":"Satu bukaan dari album lipat 26 lembar ganda; tinta dan warna di atas kertas","size":"Album (tertutup) 28 × 18 cm","credit":"Hibah Anne dan Anthony d’Offay untuk menghormati Evan Turner","p":["Satu adegan dari album sketsa Kawanabe Kyōsai (1831–1889), pelukis yang aktif dari akhir keshogunan hingga era Meiji, digambar dengan sapuan kuas cepat dan bebas di halaman album lipat. Terlatih dalam teknik ketat aliran Kanō, Kyōsai juga digemari karena gambar setan, karikatur, dan satirenya.","Judul dari museum sudah menjelaskan semuanya: “Kentut Mengacaukan Permainan Go.” Di kiri seorang pria bertopi hitam membungkuk; di kanan papan go terbang, mangkuk menumpahkan hujan batu, dan lawannya jatuh terlentang. Permainan serius hancur dalam satu letupan — Kyōsai merekam dengan kuasnya yang cepat humor kentut Jepang kuno yang sudah ada dalam gulungan abad pertengahan."],"spots":[["Pria bertopi hitam","Membungkuk dengan pantat menonjol — biang keributan?"],["Papan yang terbang","Papan go bergaris melayang miring."],["Mangkuk dan batu","Dua mangkuk terguling, batu-batunya berhamburan."],["Kipas","Kipas terbuka ikut terbang di dekat papan."],["Lawan yang terjungkal","Terlentang dengan mata terbelalak."],["Sapuan kuas","Garis tinta yang kuat, seakan dibuat sekali jadi tanpa sketsa."]]},"yokuts":{"title":"Nampan Permainan Untung-untungan","artist":"Penganyam Yokuts (nama tidak diketahui)","date":"sekitar 1900","place":"Amerika Serikat (dekat Dunlap, California)","game":"Huuchuish (dadu kulit kenari)","medium":"Serat tumbuhan (anyaman gulung)","size":"Tinggi 5,1 cm, diameter 61 cm","credit":"Dibeli dengan dana dari Ny. Leonard S. Florsheim Jr.","p":["Banyak masyarakat adat California memainkan permainan untung-untungan. Nampan ini dipakai untuk huuchuish, permainan dadu yang hanya dimainkan perempuan: delapan dadu kulit kenari dilempar ke nampan, dan skor dihitung dengan batang kecil.","Motif melingkar yang dianyam di nampan menggambarkan permainan itu sendiri — dadu, batang penghitung, dan para pemainnya (catatan museum). Ini alat permainan yang membawa gambar permainannya sendiri. Di foto, dadu kulit kenari diletakkan di atas dan di sekitar nampan."],"spots":[["Para pemain","Sosok-sosok mengitari tepi — orang yang ikut bermain."],["Batang penghitung","Kumpulan garis tegak pendek: batang untuk menghitung skor."],["Motif bundar","Motif bundar kecil — mungkin dadunya?"],["Dadu kenari","Dadu dari kulit kenari. Delapan dilempar ke nampan."],["Pita segitiga","Pita segitiga gelap melingkar penuh."],["Pusat","Anyaman berpilin keluar dari tengah, dikelilingi lingkaran putus-putus."]]},"hokkei":{"title":"Ushiwakamaru Mengalahkan Benkei dalam Sugoroku","artist":"Totoya Hokkei","date":"sekitar 1825","place":"Jepang (zaman Edo)","game":"Ban-sugoroku","medium":"Surimono (cetak balok kayu berwarna, shikishiban)","size":"21,8 × 19,1 cm","credit":"Hibah Helen C. Gunsaulus","p":["Sebuah surimono karya Totoya Hokkei (1780–1850), murid Hokusai. Surimono adalah cetakan pesanan pribadi — sering oleh kelompok puisi, dengan sajak mereka sendiri — dan dibuat lebih mewah daripada ukiyo-e komersial, dengan kertas bagus dan pigmen logam.","Ushiwakamaru, nama kecil pahlawan Minamoto no Yoshitsune, dan biksu prajurit raksasa Benkei. Pertemuan mereka yang terkenal adalah duel di Jembatan Gojō di Kyoto, tetapi di sini pertarungan menjadi permainan sugoroku: si anak duduk tenang di balik papan, sementara Benkei dengan tombak di punggung menggaruk kepala karena kalah. Tampaknya ini gubahan yang jenaka."],"spots":[["Papan sugoroku","Papan berbentuk kotak dengan bidak putih dan hitam."],["Benkei menggaruk kepala","Berbaju zirah lengkap, yang kalah menggaruk kepala."],["Ushiwakamaru","Sang pahlawan muda, duduk di balik papan."],["Tombak","Mata naginata besar milik Benkei."],["Sajak","Sajak di kanan atas — mungkin dari kelompok yang memesan cetakan ini."],["Tanda tangan","Tanda tangan Hokkei di bingkai kanan bawah."]]},"vorsterman":{"title":"Para Pemain Backgammon (adegan malam)","artist":"Lucas Emil Vorsterman, menurut Adam de Coster","date":"sekitar 1630","place":"Flandria (Antwerpen)","game":"Backgammon","medium":"Grafir di atas kertas warna gading","size":"Gambar 25,5 × 34,4 cm","credit":"Koleksi Bernard F. Rogers","p":["Adam de Coster adalah pelukis terkemuka adegan malam bercahaya lilin di Antwerpen sekitar 1630, ketika Vorsterman di kota yang sama mengukir karya pelukis populer sezamannya. Murid Rubens ini berselisih dengan gurunya lalu pergi ke Inggris, dan sesudahnya membuat grafir yang lebih kuat kontrasnya, bergaya, ala Caravaggio seperti ini.","Di sekeliling meja di ruangan gelap, para pria berkumpul di depan papan backgammon. Mengikuti cara De Coster mengolah cahaya, dua nyala lilin menerangi wajah-wajah di sekitar meja (catatan museum). Di kanan, seorang pemuda pemain lute memandang ke arah kita."],"spots":[["Papan","Papan backgammon yang terbuka seperti kotak di meja."],["Lilin","Lilin di kandilnya; nyalanya menerangi wajah-wajah."],["Pria berpipa","Bertopi lebar, ia mengisap pipa sambil menonton."],["Pria yang membelakangi","Membungkuk dengan tangan di meja."],["Pemain lute","Pemuda dengan lute yang tersenyum pada kita."],["Nama","“A. De Coster pi.” di kiri bawah, “Vorsterman” di kanan bawah."]]},"zorn":{"title":"Para Pemain Catur","artist":"Anders Zorn","date":"1891","place":"Swedia","game":"Catur","medium":"Etsa di atas kertas laid warna gading","size":"Gambar 13,5 × 9,6 cm (pelat 13,9 × 10 cm)","credit":"Koleksi etsa Anders Zorn milik Wallace L. DeWolf dan Charles Deering","p":["Etsa karya seniman Swedia Anders Zorn (1860–1920), yang termasyhur secara internasional lewat potret cat minyak dan cat air serta meninggalkan banyak karya grafis. Pelatnya tak lebih besar dari telapak tangan.","Cukup dengan garis-garis miring cepat yang ditumpuk, ruangan gelap dan dua orang muncul dari tembaga. Pria di depan, membelakangi kita, membungkuk di atas papan; sosok di seberang menunduk memikirkan langkah berikutnya. Bidak-bidaknya digambar dengan goresan tipis. Siapa yang menjadi model tidak tercatat."],"spots":[["Papan dan bidak","Bagian terang di bawah adalah papan; goresan tegak pendek adalah bidak."],["Pria di depan","Membelakangi kita, membungkuk di atas papan."],["Lawan","Menunduk, menatap papan."],["Latar gelap","Kedalaman ruangan dari garis-garis tegak."],["Garis miring","Mantelnya dibuat dari goresan diagonal cepat yang ditumpuk."],["Tanda tangan","Ditandatangani “Zorn” dengan pensil di bawah pelat."]]},"harunobu-sugoroku":{"title":"Menonton Permainan (sugoroku)","artist":"Suzuki Harunobu","date":"sekitar 1766","place":"Jepang (zaman Edo)","game":"Ban-sugoroku","medium":"Cetak balok kayu berwarna (chūban, surimono)","size":"28,5 × 21 cm","credit":"Koleksi Clarence Buckingham","p":["Suzuki Harunobu (1725?–1770) adalah tokoh utama ketika cetakan nishiki-e berwarna penuh, dicetak dari banyak balok, lahir sekitar 1765. Ini surimono terbitan pribadi, dan warnanya yang lembut berlapis menunjukkan kebaruannya.","Di ruangan dengan bunga plum, dua gadis bermain di papan sugoroku berbentuk kotak sementara gadis ketiga berdiri memandanginya. Bidak putih dan hitam berjajar di papan; gadis di kiri menjalankan bidak dan yang di kanan menjangkau papan. Pintu geser di belakang dilukis air terjun dan pohon pinus."],"spots":[["Papan sugoroku","Papan ban-sugoroku berbentuk kotak dengan bidak putih dan hitam."],["Gadis di kiri","Berkimono motif bangau kertas, menjalankan bidak."],["Gadis di kanan","Membungkuk menjangkau papan."],["Penonton","Berdiri menonton permainan, memegang benda bergagang panjang."],["Plum","Plum putih menjulurkan dahannya dari atas."],["Pintu berlukis","Pintu geser berlukis air terjun dan pinus."]]},"kota":{"title":"Maharao Kishor Singh II dari Kota Memuja Krishna sebagai Brij Rajji","artist":"Tidak diketahui","date":"sekitar 1825","place":"India (Rajasthan, Kota)","game":"Pachisi","medium":"Tempera getah, perak, dan emas di atas kertas","size":"24,5 × 18,8 cm","credit":"James Albert and Mary Gardiner Ford Memorial Fund","p":["Penguasa negara kepangeranan kecil Kota (berkuasa 1819–28), berpakaian pendeta sekte Pushti Marg, mempersembahkan pelita berapi lima. Di kuil kecil di atas altar berdiri arca logam Krishna diapit dua permaisuri — ikon yang hanya dipuja di Kota.","Banyak lampu kaca bergantung dari langit-langit, dan di anak tangga menuju altar ditata mainan dan permainan untuk menghibur Krishna dan kawan-kawannya: gajah kuningan, sapi perak, bola, dan papan pachisi (catatan museum). Kain merah berbentuk salib itulah papannya — pachisi dipersembahkan sebagai mainan sang dewa."],"spots":[["Papan pachisi","Kain merah berbentuk salib di anak tangga: papan pachisi."],["Gajah","Dua gajah kuningan di samping papan."],["Bola","Bola keemasan di anak tangga atas."],["Krishna","Arca Krishna dan dua permaisuri di kuil kecil."],["Penguasa dan pelita","Berpakaian pendeta, ia mempersembahkan pelita berapi lima."],["Lampu kaca","Banyak lampu kaca bergantung dari langit-langit."]]},"coyote":{"title":"Permainan Koyote","artist":"Pengikut José Guadalupe Posada","date":"Tanpa tanggal","place":"Meksiko","game":"Koyote dan ayam (sekeluarga dengan rubah dan angsa)","medium":"Cetak timbul dari pelat seng di atas kertas","size":"38,2 × 30,5 cm","credit":"William McCallin McKee Memorial Endowment","p":["Lembar untuk bermain, dicetak timbul dari seng seperti lembar-lembar yang dibuat Posada untuk percetakan rakyat Mexico City. Di atas tertulis “JUEGO DEL COYOTE” (permainan koyote); di sekelilingnya, koyote menyerbu kandang ayam dan seorang pria mengayunkan tongkat untuk mengusir salah satunya. Pita di bawah berbunyi “Milik Ildefonso T. Orellana”.","Aturannya tercetak di “EXPLICACION” di bawah: dua pemain, satu memegang lima belas ayam dan satu lagi seekor koyote. Ayam bergerak maju atau ke samping tetapi tak pernah mundur; koyote bergerak ke segala arah dan memakan ayam dengan melompatinya bila titik di belakangnya kosong. Ayam menang jika berhasil mengurung koyote. Ini permainan berburu yang sama dengan rubah dan angsa dari Eropa."],"spots":[["Tempat koyote","Kepala koyote di lingkaran tengah: koyote mulai dari sini."],["Tempat ayam","Lingkaran bergambar ayam: bidak ayam ditaruh di sini."],["Aturan","“EXPLICACION”: bidak, gerakan, dan cara menang."],["Judul","“JUEGO DEL COYOTE” — permainan koyote."],["Koyote mengincar ayam","Di kiri bawah, seekor koyote menerkam ayam."],["Pria bertongkat","Di kanan atas, seorang pria mengangkat tongkat pada koyote."]]},"mons":{"title":"Trictrac untuk Mons (Bergen), 1709","artist":"Pieter Nolpe (pelat dan penerbit)","date":"Pelat 1623–53; dicetak sekitar 1709","place":"Belanda (Amsterdam)","game":"Trictrac (sekeluarga dengan backgammon)","medium":"Etsa, grafir, dan sajak cetak huruf","size":"Kertas 35,8 × 18,6 cm (pelat 12,9 × 17,5 cm)","credit":"","p":["Empat pria bermain trictrac di sebuah meja. Menurut catatan museum, huruf A–D menandai Adipati Marlborough, Elektor Bayern, Tuan Ouwerkerk, dan Adipati Villeroy. Ini cetakan satir tentang pengepungan dan perebutan Mons (Bergen dalam bahasa Belanda) oleh Sekutu dari Prancis pada 1709, digambarkan sebagai permainan dengan kota sebagai taruhannya. Di ruang belakang (E), Raja Felipe V dari Spanyol bersama seorang wanita.","Pelatnya bertanda tangan Pieter Nolpe sebagai pembuat dan penerbit, tetapi Nolpe wafat awal 1650-an — kemungkinan pelat tua abad ke-17 dicetak ulang dengan tambahan huruf dan sajak baru. Sajak di bawah dibuka dengan menyebut permainan para tuan besar tak lain tiktak dan verkeer (dua permainan sekeluarga), lalu mengejek tiap pemain."],"spots":[["Papan","Papan trictrac di meja: taruhannya sebuah kota."],["A, Marlborough","Berdiri memandang papan — jenderal Inggris pemimpin Sekutu."],["B, Elektor Bayern","Tanpa topi, terenyak di kursinya."],["C, Ouwerkerk","Bertopi bulu — jenderal Belanda."],["E, ruang belakang","Di kamar belakang, Felipe V bersama seorang wanita."],["Sajak","Sajak berbahasa Belanda di bawah, mengejek pemain A sampai E."]]},"stembus":{"title":"Kotak Suara: Permainan Angsa Politik","artist":"Johan Michaël Schmidt Crans (pembuat cetakan)","date":"1867","place":"Belanda","game":"Permainan angsa (satire)","medium":"Litografi","size":"66 × 50 cm","credit":"","p":["Cetakan satir berbentuk permainan angsa. Cetakan ini terbit bersama mingguan De Nederlandsche Spectator, no. 9, 2 Maret 1867, dengan lembar aturan terpisah (catatan museum). Petak-petaknya berisi potret para menteri saat itu.","Permainan dimulai di Binnenhof, gedung parlemen di Den Haag, dan berakhir di tengah, petak 64 “Insulinde” — nama puitis Hindia Belanda — tempat potret menteri Pieter Mijer digantung dari Pulau Jawa. Mijer beralih dari Menteri Urusan Jajahan menjadi Gubernur Jenderal Hindia, dan pengangkatan itu memicu badai politik. Petak tambahan, satu lebih dari 63 yang biasa, kemungkinan ada demi lelucon penutupnya."],"spots":[["Start","Bangunan di kiri atas: permainan dimulai di Binnenhof, Den Haag."],["Potret Mijer","Petak 63: potret berbingkai Pieter Mijer, digantung dengan tali dari pulau."],["Insulinde 64","Pulau dan angka 64 di tengah: garis akhir."],["Kotak suara","“DE STEMBUS” (kotak suara) di kanan bawah: kotak dalam judul."],["Para menteri","Wajah para menteri saat itu menatap dari petak-petak."],["Ayam jantan","Seekor ayam jantan di satu petak; apa yang disindirnya tidak diketahui."]]},"koorai":{"title":"Orang Korea di Depan Permainan Papan (dari Nippon karya Siebold)","artist":"James Erxleben (litografer), menurut rancangan “Toioske”","date":"1832–52","place":"Belanda (Leiden) / orang Korea","game":"Permainan papan (kemungkinan go)","medium":"Litografi bernada, diwarnai tangan","size":"Kertas 38 × 55,5 cm","credit":"Hibah F. G. Waller","p":["Satu lembar dari NIPPON, karya besar dokter kelahiran Jerman Philipp Franz von Siebold yang diterbitkan di Leiden berdasarkan pengamatannya di pos dagang Belanda di Nagasaki (1823–30). Di kanan atas tertulis “TAB. I” dan di bawah “KOORAI” (Korea), dengan “keluarga nelayan” dalam bahasa Belanda dan Jerman. Erxleben menggambarnya di batu; lembar itu menyebut perancangnya “Toioske”.","Empat pria duduk di tanah mengelilingi papan; di kiri seorang wanita menuntun anak kecil, di kanan seorang pria berdiri dengan tongkat panjang dan kantong. Di depan tergeletak topi hitam bertepi lebar (gat). Papan itu berpetak dengan batu-batu bundar, jadi kemungkinan go (baduk dalam bahasa Korea), meski catatan hanya menyebut “permainan papan”."],"spots":[["Papan","Petak dengan batu bundar: kemungkinan permainan go."],["Topi hitam","Topi hitam bertepi lebar (gat) di tanah."],["Ibu dan anak","Wanita yang menuntun anak sambil menonton."],["Pria yang berdiri","Berdiri dengan tongkat panjang dan kantong."],["Pria yang membungkuk","Berjaket biru, mengamati papan."],["Judul","“KOORAI” (Korea), dengan “keluarga nelayan” dalam bahasa Belanda dan Jerman."]]},"cairo":{"title":"Orang-orang Mengelilingi Permainan Papan di Depan Kedai Kopi (Kairo)","artist":"Délié & Béchard (Hippolyte Délié dan Émile Béchard)","date":"sekitar 1869–90","place":"Mesir (Kairo)","game":"Permainan papan (kemungkinan catur)","medium":"Cetak albumen","size":"10,8 × 16,4 cm","credit":"","p":["Foto karya Hippolyte Délié dan Émile Béchard, fotografer Prancis yang membuka studio di Kairo. Kartonnya bertuliskan nama studio, “dekat Taman Ezbekiya”, dan “Kairo (Mesir)”. Foto semacam ini dibeli para pelancong sebagai kenang-kenangan dari Mesir.","Para pria duduk di tanah di depan toko berjendela kisi, mengelilingi papan di atas dudukan rendah. Bidak-bidak tinggi berdiri di papan, jadi kemungkinan catur (syatranj dalam bahasa Arab), meski catatan museum hanya menyebut “permainan papan”. Semua diam tak bergerak demi pencahayaan yang lama."],"spots":[["Papan dan bidak","Papan di dudukan rendah dengan bidak tinggi: kemungkinan catur."],["Jendela kisi","Jendela berkisi kayu, khas rumah-rumah lama Kairo."],["Pria bertongkat","Duduk memegang tongkat, menonton permainan."],["Keranjang","Keranjang anyaman di tanah."],["Anak yang menonton","Seorang anak mengintip papan dari belakang."],["Nama studio","“AU JARDIN DE L’ESBÉKIEH” dan “CAIRE (EGYPTE)” di karton."]]},"vanmour":{"title":"Sekelompok Orang Armenia Bermain Kartu","artist":"Jean-Baptiste Vanmour","date":"sekitar 1720–37","place":"Kesultanan Utsmaniyah (Istanbul)","game":"Kartu","medium":"Cat minyak di atas kanvas","size":"44,5 × 58,5 cm","credit":"","p":["Vanmour yang lahir di Flandria pergi ke Istanbul pada 1699 bersama duta besar Prancis dan tinggal di kota itu hingga wafat, melukis upacara istana dan kehidupan sehari-hari warganya. Museum mencatat bahwa dari pakaiannya para pria ini adalah orang Armenia.","Di bawah cahaya sebatang lilin besar, para pria dan wanita bermain kartu mengelilingi meja berkain merah. Kartu-kartu yang sudah dibagikan tergeletak di meja, dan sebagian memperhatikan kartu di tangan. Di sudut kiri seorang wanita tua memintal benang. Catatan tidak menyebut permainan apa itu."],"spots":[["Kartu di meja","Kartu di atas meja berkain merah."],["Lilin besar","Sebatang lilin menerangi seluruh kelompok."],["Wanita tua memintal","Wanita tua memintal di sudut kiri."],["Wanita melihat kartunya","Di paling kanan, seorang wanita memandangi kartunya."],["Pria berbulu","Pria bermantel berpinggiran bulu; pakaiannya menandai orang Armenia."],["Mencondongkan badan","Seseorang condong ke meja dengan kartu di tangan."]]},"algiers":{"title":"Tiga Pria Bermain Permainan Papan (Aljir)","artist":"Anonim","date":"1851–1900","place":"Aljazair (Aljir)","game":"Permainan papan (kemungkinan backgammon)","medium":"Cetak albumen","size":"14,0 × 10,0 cm","credit":"","p":["Foto tanpa nama pembuat, dengan tulisan tangan “Alger” (Aljir) di bawah gambar. Dengan kursi dan meja kecil di depan latar polos, foto ini kemungkinan dibuat di studio. Foto orang-orang Afrika Utara semacam ini dibeli pelancong dan kolektor.","Dua pria duduk berhadapan di depan papan berbingkai, dan pria di kanan menjulurkan tangan ke sebuah bidak. Bidak-bidak bundar bertumpuk di papan, jadi kemungkinan backgammon (di sana disebut tawla, antara lain), meski catatan hanya menyebut “permainan papan”. Di meja kecil di depan ada perlengkapan kopi."],"spots":[["Papan dan bidak","Papan berbingkai dengan bidak bundar bertumpuk."],["Penonton yang berdiri","Pria bersabuk kain berdiri di belakang menonton permainan."],["Pria tua di kiri","Pria tua berikat kepala, termenung."],["Pria di kanan","Berkerudung kain putih, membungkuk ke papan."],["Perlengkapan kopi","Baki dan cangkir kecil di meja kecil berukir tembus."],["Tangan yang melangkah","Tangan pemain kanan yang hendak mengambil bidak."]]},"circo":{"title":"Permainan Sirkus (Juego del Circo)","artist":"Manuel Manilla (?)","date":"Tanpa tahun","place":"Meksiko","game":"Permainan taruhan dengan dua dadu","medium":"Cetak timbul (ukiran kayu ujung atau fotogravur) pada kertas cokelat muda","size":"26,2 × 35,0 cm","credit":"","p":["Lembar permainan yang dikaitkan, dengan tanda tanya, pada pembuat cetakan Meksiko Manuel Manilla. Di kanan bawah tertera penjualnya, toko cetakan “El Teatro”, beserta alamatnya. Lembaran murah semacam ini dijual di jalan dan tampaknya dimainkan begitu saja.","Di tengah ada tenda sirkus, dikelilingi penunggang akrobat, menara manusia, orang kuat, dan lainnya, masing-masing bernomor 2 sampai 12. “Penjelasan” di kiri atas menyebut siapa saja, anak-anak juga, boleh bermain: lempar dua dadu lalu taruh taruhan di kotak yang sesuai, atau ambil taruhan yang sudah ada di sana. Siapa yang melempar 12 mengambil semuanya."],"spots":[["Tenda sirkus","Judul “JUEGO DEL CIRCO” dan tenda yang menjadi kotak 12."],["Aturan main","Aturan di bawah judul “ESPLICACION”."],["Penunggang akrobat","Penari di punggung kuda yang berlari: kotak 6."],["Menara manusia","Seorang berdiri di bahu orang lain: kotak 4."],["Orang kuat","Pria mengangkat beban berbentuk meriam: kotak 8."],["Nama toko cetakan","“De venta, Estampería ‘El Teatro’” dan alamatnya."]]},"loteria":{"title":"Kartu Gambar Lotería","artist":"José Guadalupe Posada","date":"1880–1913","place":"Meksiko","game":"Lotería (permainan menyebut gambar)","medium":"Cetak timbul (ukiran kayu ujung atau fotogravur) pada kertas cokelat muda","size":"30,0 × 40,0 cm","credit":"","p":["Pembuat cetakan Meksiko Posada menggambar sangat banyak ilustrasi untuk penerbit Kota Meksiko Antonio Vanegas Arroyo, yang lembaran murahnya memuat berita, lagu, dan permainan. Lembar ini bertuliskan judul “JUEGO DE LOTERIA” dan nama Vanegas Arroyo.","Tiga puluh delapan gambar kecil bernama memenuhi lembar ini: bintang, bulan, kalajengking, setan, tengkorak, ayam jantan, percetakan, dan lainnya. Dalam lotería, mirip bingo, pemanggil menarik kartu dan menyebut gambarnya, lalu pemain menandai gambar itu di papan mereka dengan kacang atau semacamnya. Lembar ini kemungkinan dipotong menjadi kartu."],"spots":[["Judul dan penerbit","“JUEGO DE LOTERIA” dan nama usaha Vanegas Arroyo."],["Bintang","“ESTRELLA”, gambar pertama di kiri atas."],["Bulan","“LUNA”, bulan sabit berwajah."],["Maut","“MUERTE”: kerangka bersabit yang meniup suling."],["Tlachiquero","“TLACHIQUERO”: pria pengumpul getah agave."],["Percetakan","“IMPRENTA”: pekerja di mesin cetak, tempat lembaran seperti ini dibuat."]]},"jeupol":{"title":"“Jeu polonais”, atau Papan Dam","artist":"Anonim","date":"1833–1900","place":"Belgia atau Belanda","game":"Dam (papan 10 × 10)","medium":"Cetak kayu dengan teks cetak timah","size":"32,2 × 39,6 cm","credit":"","p":["Selembar cetakan berjudul bahasa Prancis dan Belanda, “JEU POLONAIS OF DAMSPEL”. “Jeu polonais” (permainan Polandia) adalah nama Prancis untuk dam di papan 10 × 10. Di kanan atas ada nomor seri penerbit, “n. 106”.","Seperti catatan museum, ada 100 kotak, 50 putih dan 50 hitam, dengan bingkai hias di kiri dan kanan. Bidaknya tidak dicetak, jadi kemungkinan ini papan murah yang dimainkan begitu saja dengan kacang atau kancing. Bekas lipatan masih terlihat di kertas."],"spots":[["Judul","Tulisan “JEU POLONAIS OF DAMSPEL”."],["Nomor seri","Nomor penerbit “n. 106”."],["Bingkai kiri","Deretan motif bunga bundar."],["Bingkai kanan","Motif yang sama di sisi lain."],["Seratus kotak","Papan 10 × 10; kotak gelap diarsir garis halus."],["Lipatan","Bekas lipatan di kertas; mungkin dibawa dalam keadaan terlipat."]]},"dkaart":{"title":"Domino dan Kartu untuk Digunting","artist":"Anonim (Brepols)","date":"1800–1833","place":"Belgia (Turnhout)","game":"Domino dan kartu","medium":"Cetak kayu diwarnai biru, merah, dan kuning; teks cetak timah","size":"34,3 × 41,9 cm","credit":"","p":["Menurut catatan museum, lembar ini memuat 32 kartu remi dan 28 batu domino untuk digunting. Ini nomor 114 dalam daftar penerbit Brepols, dengan nama pengecer “D. Pouwels, Bergen-op-Zoom” di bawah. Judulnya dalam bahasa Belanda dan Prancis.","Di kiri, 28 batu dari kosong-kosong sampai enam-enam tersusun segitiga. Di kanan ada 32 kartu, tujuh sampai sepuluh ditambah kartu bergambar dan as tiap jenis: satu set untuk permainan seperti piket. Karena tak pernah digunting, kita melihatnya seperti saat keluar dari mesin cetak."],"spots":[["Judul","Tulisan “DOMINO EN KAARTSPEL”."],["Kosong-kosong","Puncak segitiga: batu tanpa titik."],["Enam-enam","Batu tertinggi, di ujung kanan baris bawah."],["As sekop","Kartu kedua di kolom kiri."],["Kartu bergambar","Raja yang diwarnai merah, biru, dan kuning."],["Pengecer","“D. POUWELS, Bergen-op-Zoom” di bawah."]]},"apen":{"title":"Dua Monyet Bermain Trictrac","artist":"Quirin Boel, menurut David Teniers","date":"1635–1690","place":"Flandria","game":"Trictrac (kerabat backgammon)","medium":"Etsa","size":"11,0 × 14,5 cm","credit":"","p":["Satu lembar dari seri berisi halaman judul dan enam cetakan, tempat monyet memerankan kegiatan manusia. Di kiri bawah tertulis “D. Teniers merancang dan menerbitkan, dengan hak istimewa”: Quirin Boel mengetsa rancangan pelukis Flandria Teniers.","Seperti catatan museum, dua monyet duduk di lantai dengan papan trictrac di antara mereka. Yang kiri minum anggur dari gelas; yang kanan, bertopi bulu ayam jago, menjulurkan tangan ke sebuah bidak. Kemungkinan ini mengejek orang yang larut dalam minuman dan judi."],"spots":[["Papan","Papan trictrac lipat di lantai, dengan segitiga dan bidaknya."],["Monyet kiri","Monyet berjaket yang duduk di depan papan."],["Gelas anggur","Gelas yang diangkat monyet kiri."],["Topi berbulu","Bulu ayam jago di topi monyet kanan."],["Kendi","Kendi di dekat kaki monyet kiri."],["Tulisan","“D Teniers in et excud cum privilegio”."]]},"dstereo":{"title":"Para Pria Bermain Domino di Meja (Foto Stereo)","artist":"Anonim","date":"1850–1880","place":"Tidak diketahui (tulisan bahasa Belanda)","game":"Domino","medium":"Cetak albumen (foto stereo)","size":"8,5 × 17,0 cm","credit":"","p":["Sebuah foto stereo: dua foto yang hampir sama berdampingan. Bila dilihat dengan stereoskop, keduanya menyatu menjadi satu adegan berkedalaman. Di tepi kiri tertulis tangan “Het dominospel” (permainan domino).","Sebuah meja diletakkan di bawah matahari di depan bangunan, dan para pria berkemeja memegang batu domino. Dua orang berdiri menonton; pria di kanan memakai topi putih. Karena semua harus diam, adegan ini kemungkinan diatur untuk kamera."],"spots":[["Batu di meja","Batu domino yang dipegang tertutup."],["Pria bertopi putih","Duduk di kanan dengan batunya."],["Pria berselendang leher","Berdiri menonton dari atas."],["Pria di kiri","Pemuda yang bertopang siku memandangi batunya."],["Tulisan","“Het dominospel.” di tepi kiri."],["Gambar kedua","Foto kanan, diambil dari titik yang sedikit bergeser: berdua tampak tiga dimensi."]]},"gojo":{"title":"Dua Wanita Bermain Go","artist":"Anonim","date":"1870–1891","place":"Jepang","game":"Kemungkinan go","medium":"Cetak albumen diwarnai tangan","size":"9,0 × 13,5 cm","credit":"","p":["Foto hitam-putih yang diwarnai dengan kuas. Foto semacam ini dibuat di studio-studio Yokohama dan tempat lain sebagai cendera mata bagi orang asing. Foto ini dulu ditempel di album perjalanan ke Manila.","Berlatar hiasan ceruk dan sekat lipat, dua wanita duduk berhadapan di depan papan berkaki, dan wanita di kiri sedang meletakkan batu. Ada batu putih dan hitam di papan, jadi kemungkinan go, meski catatan museum menyebut “permainan papan”. Di baki depan ada kue dan mangkuk."],"spots":[["Papan dan batu","Papan tebal berkaki dengan batu putih dan hitam."],["Tangan yang melangkah","Wanita kiri meletakkan batu."],["Wanita di kiri","Menoleh ke arah kita; obinya diikat simpul besar."],["Wanita di kanan","Berkimono belang, tangannya di dekat papan."],["Baki dan mangkuk","Kue dan cangkir di depan."],["Bunga","Vas bunga di atas tatakan di belakang."]]},"meade":{"title":"Dua Pria Bermain Catur","artist":"Charles Richard Meade dan Henry William Mathew Meade","date":"1852","place":"Amerika Serikat","game":"Catur","medium":"Dagerotipe","size":"6,9 × 8,3 cm","credit":"","p":["Sebuah dagerotipe dari studio kakak-beradik Meade, fotografer kelahiran Inggris yang bekerja di Amerika. Dagerotipe membentuk gambar langsung di lempeng tembaga berlapis perak, jadi setiap buahnya unik dan tak bisa dicetak ulang; yang ini disimpan dalam kotak kulit kecil di balik bingkai emas.","Dua pemuda menghadap papan catur di atas meja kecil; yang kiri menyentuh sebuah bidak. Yang kanan, tangan di dada, mengamati papan. Karena harus diam lama, langkah ini kemungkinan hanya pose."],"spots":[["Papan catur","Papan dan bidak putih di atas meja kecil bertaplak bunga."],["Pria di kiri","Jarinya di sebuah bidak."],["Pria di kanan","Menunduk memandangi papan."],["Tangan di dada","Tangan pemain kanan yang sedang berpikir."],["Taplak","Meja kecil bertaplak kain bermotif bunga."],["Bingkai emas","Bingkai dan kotak yang melindungi lempeng."]]},"weiqidai":{"title":"Pemandangan dengan Dewa Tao Bermain Weiqi","artist":"Diatribusikan kepada Dai Jin","date":"Dinasti Ming, abad ke-15–16","place":"Tiongkok","game":"Weiqi (go)","medium":"Gulungan gantung; tinta dan warna di atas sutra","size":"175,2 × 106,7 cm","credit":"","p":["Gulungan gantung besar yang diatribusikan kepada pelukis Ming Dai Jin (sekitar 1388–1462). Berasal dari Zhejiang dan dikenal dengan lanskapnya yang kuat, ia kemudian dianggap pendiri aliran Zhe. Di bawah tebing menjulang dan pohon besar, manusia dilukis kecil.","Di tanah yang teduh, dua dewa duduk berhadapan di depan papan weiqi bergaris, dengan piring buah dan guci di samping. Sosok yang berjongkok di kiri mengingatkan pada penebang kayu yang menonton para dewa bermain di gunung sampai gagang kapaknya lapuk (legenda Lanke), meski judul museum hanya menyebut dewa Tao bermain weiqi."],"spots":[["Papan","Papan berbingkai dengan kisi halus."],["Dewa berjanggut","Dewa berjanggut panjang, duduk santai."],["Dewa bertopi biru","Condong ke papan; di dekat lututnya ada mangkuk batu."],["Sosok berjongkok","Mengintip papan dari kiri; mungkin si penebang kayu dalam legenda."],["Buah dan guci","Piring dan guci di seberang papan."],["Tanda tangan dan cap","Tanda tangan dan dua cap merah di kanan atas."]]},"reise":{"title":"Perjalanan Keliling Dunia, Lewat Air dan Darat","artist":"Anonim","date":"Abad ke-19","place":"Kemungkinan wilayah berbahasa Jerman","game":"Permainan balap satu dadu dengan taruhan","medium":"Litografi","size":"42,5 × 33,7 cm","credit":"","p":["Lembar permainan berjudul bahasa Jerman “Perjalanan keliling dunia, lewat air dan darat: permainan dadu yang baru dan menghibur”. Papan bundar berisi kotak 1 sampai 41, dengan gambar balon udara, kapal layar, kapal uap, lokomotif, orang dari berbagai bangsa, dan lainnya. Di kanan bawah ada nomor “No. 107”.","Di bawahnya tercetak aturan dalam bahasa Jerman, Inggris, Belanda, dan Prancis. Setiap pemain membayar dulu 15 mark ke “kantong perjalanan” bersama, lalu bergiliran melempar satu dadu dan memajukan tandanya. Berhenti di gambar besar menang 2 mark, nomor tanpa gambar didenda 2 mark, dan yang mencapai 41 mengambil semua sisanya."],"spots":[["41: kereta pos","Tujuan di tengah: kereta kuda dengan penumpang dan kusir."],["1: orang Inggris","Kotak awal, “Engländer” bertopi tinggi."],["Balon udara","Kotak dengan balon di langit."],["Kapal layar","Kapal dengan layar terkembang."],["Lokomotif","Lokomotif uap yang mengepulkan asap."],["Aturan","Aturan yang dicetak dalam empat bahasa."]]},"huchten":{"title":"Dadu Penentu Hidup atau Mati","artist":"Jan van Huchtenburg","date":"1680–1720","place":"Belanda","game":"Dadu","medium":"Cat minyak di atas kanvas","size":"67,5 × 76,0 cm","credit":"","p":["Karya pelukis Belanda Jan van Huchtenburg (1647–1733), yang dikenal dengan lukisan pertempuran, bertanda tangan di kiri bawah. Judul museumnya “Permainan dadu untuk nyawa”. Di luar sebuah benteng, dua tahanan melempar dadu di atas genderang, dikelilingi perwira dan prajurit.","Di kanan belakang berdiri tiang gantungan, dan dari tembok benteng di kiri para prajurit menonton. Kemungkinan ini prajurit terhukum yang mengundi dengan dadu siapa yang akan dieksekusi. Seorang tahanan menunjuk genderang; yang lain berlutut memandangi lemparan."],"spots":[["Genderang dan dadu","Genderang menjadi meja tempat dadu dilempar."],["Tahanan yang menunjuk","Berdiri sambil menunjuk genderang."],["Tahanan yang berlutut","Berkemeja putih, membungkuk di atas genderang."],["Perwira berkuda","Bertopi, memandang dari atas kuda."],["Tiang gantungan","Tiang gantungan di kanan atas."],["Prajurit di tembok","Prajurit yang menonton dari tembok benteng."]]},"vertu":{"title":"Permainan Kebajikan (Spel der Deugd)","artist":"Jan Gerritsz. Visser (rancangan J. Voorman)","date":"1798","place":"Belanda","game":"Permainan taruhan dengan dua dadu","medium":"Gravir, etsa, dan cetak timah","size":"56,9 × 38,0 cm","credit":"","p":["Lembar permainan besar berjudul bahasa Belanda dan Prancis “Permainan Kebajikan”. Di tengah kuil bertiang duduk Kebajikan, dengan Kemakmuran berdiri di kiri dan Kemiskinan di kanan. Di tiang-tiang tergantung medali kebajikan seperti Ketulusan, Rasa Syukur, dan Cinta, sedangkan di alasnya ada sifat buruk seperti Kekikiran, Kesombongan, dan Kemalasan.","Menurut aturan di bawah, permainan ini memakai dua dadu atau undian. Dengan dadu, para pemain bertaruh total 63, lalu melempar bergiliran mengikuti arah matahari. Tiap lemparan menyebut satu kebajikan atau keburukan: dobel enam, Kebajikan, mengambil seluruh taruhan, dan dobel satu, Keburukan, membayar delapan. Di bawah tiap gambar, “T” berarti ambil dan “B” berarti bayar."],"spots":[["Judul","“SPEL DER DEUGD” di bidang segitiga atap."],["Kebajikan","Kebajikan bertakhta di tengah; dobel enam mengambil semuanya."],["Kemakmuran","Kemakmuran dengan tanduk kelimpahan."],["Keburukan","Dobel satu, Keburukan: anak yang mengangkat cawan."],["Kekikiran","Kekikiran di alas; “B” dan dadu menunjukkan bayarannya."],["Aturan","Aturan yang tercetak rapat di bawah."]]},"charros":{"title":"Para Charro Penyelundup: Permainan Dadu","artist":"José Guadalupe Posada","date":"Tanpa tahun","place":"Meksiko","game":"Permainan balap dengan tiga dadu","medium":"Litografi","size":"29,9 × 40,4 cm","credit":"","p":["Permainan balap bergambar karya Posada, berjudul “LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS” (Para charro penyelundup / Permainan dadu). Di bawah tertera percetakan A. Vanegas Arroyo, Meksiko, dan Posada menandatanganinya di kanan bawah. Charro, penunggang kuda Meksiko, berpacu bersombrero di sudut-sudutnya.","Kotak-kotak bundar berbingkai tali berkelok di seluruh papan, berisi hewan, orang, kereta api, dan lainnya. “Penjelasan” di kanan atas menyebut tiga dadu. Tiga angka satu pada lemparan pertama menang; jatuh di tengkorak kalah; di rusa mengambil dari kas, di perampok membayar, dan di singa diam sampai ada pemain lain datang."],"spots":[["Judul","“LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS”."],["Penjelasan","Aturan di bawah judul “EXPLICACION”."],["Para pemain","Orang-orang di sekitar meja bermain papan, kiri bawah."],["Dadu","Tiga dadu di tengah papan."],["Charro berkuda","Charro berpacu sambil memutar laso."],["Percetakan","“IMPRENTA DE A. VANEGAS ARROYO, MÉXICO”."]]},"snuffwq":{"title":"Botol Tembakau Sedot dengan Pemain Weiqi","artist":"Tiongkok","date":"Dinasti Qing, tanda dan masa pemerintahan Daoguang (1820–50)","place":"Tiongkok","game":"Weiqi (go)","medium":"Porselen dilukis email di atas glasir","size":"Tinggi 5,7 cm","credit":"","p":["Botol kecil untuk membawa tembakau sedot di Tiongkok masa Qing. Menurut catatan museum, botol ini bertanda masa pemerintahan Daoguang dan berasal dari 1820–50. Pada badannya yang berupa porselen putih setinggi sekitar enam sentimeter dilukis pemandangan gunung dan sosok manusia.","Di dekat batu seperti gua, dua orang tua duduk berhadapan di depan papan weiqi di atas meja biru; yang kiri hendak meletakkan batu. Di belakangnya seorang anak memegang tongkat menonton. Tema ini kemungkinan mengingatkan pada kisah penebang kayu yang menonton para dewa bermain."],"spots":[["Papan","Papan di atas meja biru dengan kisi halus."],["Orang tua berjanggut","Berjubah ungu, menjulurkan tangan ke papan."],["Orang tua di seberang","Duduk di kanan, mengangkat tangan."],["Anak bertongkat","Menonton dari belakang."],["Gua batu","Batu seperti gua di belakang."],["Tutup","Tutup berwarna hijau."]]},"ostade":{"title":"Pemain Trictrac di Sebuah Kedai","artist":"Adriaen van Ostade","date":"1653","place":"Belanda (Haarlem)","game":"Trictrac (kerabat backgammon)","medium":"Etsa","size":"8,5 × 7,4 cm","credit":"","p":["Etsa seukuran telapak tangan karya pelukis Haarlem Ostade, yang dikenal dengan adegan kehidupan petani, bertanda tangan “A. ostade” di bawah. Di kedai yang gelap, cahaya dari jendela berbingkai timah menerangi orang-orang.","Di meja kiri dua pria berhadapan di depan papan trictrac, sementara orang ketiga mengintip dari belakang. Di kanan seorang pria bersandar ke dinding dengan cangkir di tangan. Kendi besar tergeletak di lantai; tampak seperti sore yang malas di kedai."],"spots":[["Papan","Papan trictrac di atas meja."],["Pemain kiri","Pria bertopi menghadap papan."],["Pemain kanan","Membungkuk di atas papan."],["Penonton","Pria yang berdiri di belakang menonton."],["Yang bersantai","Duduk di dekat dinding, cangkir di tangan."],["Jendela timah","Jendela berpanel belah ketupat tempat cahaya masuk."]]},"lenain":{"title":"Para Pemain Dadu","artist":"Pengikut Mathieu Le Nain","date":"1630–1680","place":"Prancis","game":"Dadu","medium":"Cat minyak di atas kanvas","size":"92,8 × 119,7 cm","credit":"","p":["Karya pengikut Mathieu, si bungsu dari kakak-beradik Le Nain di Prancis. Museum mencatat bahwa sketsa komposisi serupa karya Gabriel de Saint-Aubin ada di Bibliothèque nationale, Paris.","Tiga pria mengelilingi meja bundar kecil di luar ruangan dan melempar dadu; dua lainnya menonton, yang kiri memeluk botol. Di kanan ada dua anjing greyhound ramping, dan di balik bukaan terbentang pemandangan luas. Benda putih kecil di meja adalah dadunya."],"spots":[["Dadu di meja","Dadu di atas meja bundar."],["Pria bertopi terang","Duduk, menjulurkan tangan memeriksa lemparan."],["Pria berbaju hitam","Pemuda berdiri bertolak pinggang."],["Anak di belakang","Menonton dari balik meja."],["Pria berbotol","Di kiri, tersenyum kepada kita."],["Dua anjing","Anjing ramping di kanan."]]},"tunisie":{"title":"Permainan Kartu di Depan Kedai Kopi Arab (Bagian Tunisia, Pameran Dunia Antwerpen)","artist":"Anonim (dicetak Ch. Bernhoeft)","date":"1894","place":"Belgia (Antwerpen)","game":"Kartu","medium":"Kolotipe","size":"15,4 × 21,6 cm","credit":"","p":["Satu dari 49 lembar tentang Pameran Dunia Antwerpen 1894, bertuliskan “EXPOSITION UNIVERSELLE D’ANVERS 1894” di atas dan “Tunisia. Permainan kartu di depan kedai kopi Arab” di bawah. Dicetak oleh Bernhoeft, fotografer istana di Luksemburg.","Foto ini diambil di alun-alun berkubah dan bermenara yang dibangun untuk bagian Tunisia di pameran. Para pria berpakaian Tunisia bermain kartu mengelilingi meja kecil berubin; seorang mengisap pipa air, dan ada baki cangkir di dekatnya. Di kanan duduk pengunjung berjas: kemungkinan ini pertunjukan kehidupan negeri yang jauh."],"spots":[["Meja kartu","Pria-pria memegang kartu di sekitar meja kecil berubin."],["Pipa air","Selang pipa air pria di kiri."],["Pengunjung berjas","Pria berjas yang duduk di kanan, kemungkinan pengunjung pameran."],["Baki cangkir","Cangkir kecil di bawah meja."],["Kubah dan menara","Bangunan bergaya Tunisia yang didirikan untuk pameran."],["Keterangan","“TUNISIE” dan “PARTIE DE CARTES DEVANT UN CAFÉ ARABE”."]]},"laghouat":{"title":"Para Kaid dari Sekitar Laghouat","artist":"Anonim","date":"1880–1890","place":"Aljazair (sekitar Laghouat)","game":"Kemungkinan domino","medium":"Cetak albumen","size":"20,9 × 27,0 cm","credit":"","p":["Foto berjudul “Tipe-tipe Aljazair. Para kaid dari sekitar Laghouat”, ditempel di album dan bernomor cetak “239”. Kaid adalah gelar pemimpin lokal di Aljazair pada masa kekuasaan Prancis.","Para pria berjubah putih duduk di tikar di depan tembok tanah, menyusun batu-batu panjang di atas meja rendah. Dari susunannya kemungkinan domino, meski catatan museum hanya menyebut “permainan”. Di depan ada baki teh dan alas kaki yang dilepas."],"spots":[["Batu di meja rendah","Batu panjang yang disusun berderet di meja."],["Baki teh","Gelas dan teko di baki depan."],["Alas kaki","Sepatu yang ditinggalkan di samping tikar."],["Sosok yang berdiri","Seseorang berdiri di dekat tembok, menonton."],["Tembok tanah","Tembok tanah kasar di belakang."],["Tikar","Tikar anyaman tempat mereka duduk."]]},"hangong":{"title":"Para Dayang Istana (Pagi Musim Semi di Istana Han), detail","artist":"Salinan menurut Qiu Ying","date":"Dinasti Qing (1644–1911)","place":"Tiongkok","game":"Weiqi (go)","medium":"Gulungan mendatar; tinta dan warna di atas sutra","size":"36,2 × 454,4 cm (seluruh gulungan)","credit":"","p":["Detail dari gulungan mendatar sepanjang lebih dari empat setengah meter, salinan masa Qing atas komposisi pelukis Ming Qiu Ying (1494–1552). Di istana pada hari musim semi, para dayang, gadis, dan pelayan bermain ayunan, bermain, mengagumi peoni, bermusik, memetik qin, serta memberi makan burung beo dan ikan.","Dalam adegan ini dua wanita berhadapan di depan papan weiqi di balik pagar, sementara yang lain membungkuk menonton. Di depan ada batu hias dalam wadah berbentuk teratai, dan para pelayan membawa alat musik dan bungkusan. Seperti kata museum, gulungan ini mengidealkan kehidupan wanita di bagian dalam istana."],"spots":[["Papan","Papan weiqi di meja di balik pagar."],["Pemain yang meletakkan batu","Wanita berbaju ungu muda yang menjangkau papan."],["Para penonton","Wanita-wanita yang membungkuk melihat permainan."],["Wanita berkipas","Wanita memegang kipas bundar di antara tiang."],["Batu hias","Batu biru dalam wadah berbentuk teratai."],["Pelayan dengan alat musik","Pelayan yang membawa kemungkinan sebuah pipa."]]},"homerbg":{"title":"Backgammon","artist":"Winslow Homer","date":"sekitar 1877","place":"Amerika Serikat","game":"Backgammon","medium":"Ukiran kayu ujung","size":"","credit":"","p":["Ukiran kayu menurut gambar pelukis Amerika Winslow Homer (1836–1910), yang semasa muda membuat banyak ilustrasi untuk cetakan seperti ini. Di bawahnya tercetak “396.—BACKGAMMON.—WINSLOW HOMER.”, jadi kemungkinan ini lembar bernomor dari buku atau majalah.","Dua wanita duduk berhadapan di sofa berhias, bermain backgammon di papan yang diletakkan di pangkuan mereka. Di atas papan ada benda bundar putih, tetapi tidak jelas apa itu. Lipatan rok panjang dan sandaran tangan sofa yang melingkar diukir dengan garis halus."],"spots":[["Papan","Papan di pangkuan kedua wanita."],["Wanita di kiri","Rambut disanggul, menjangkau papan."],["Wanita di kanan","Mencondongkan badan mengamati papan."],["Sandaran sofa","Sandaran tangan berbentuk ikal."],["Rok","Rok panjang dengan lipatan bergaris halus."],["Keterangan","“396.—BACKGAMMON.—WINSLOW HOMER.” di bawah."]]},"chessst":{"title":"Pria dan Wanita Bermain Catur (Foto Stereo)","artist":"Anonim","date":"1852–1858","place":"Tidak diketahui","game":"Catur","medium":"Foto stereo, diwarnai","size":"8,3 × 16,5 cm","credit":"","p":["Sepasang foto yang ditempel sebagai foto stereo, dikenal dalam bahasa Inggris sebagai “The Chess Players”. Dilihat dengan stereoskop, papan dan bidak seolah menonjol. Warna ditambahkan di atas gambar hitam-putih, pada tirai merah dan gaun kuning.","Wanita bergaun kuning memegang sebuah bidak, sementara pria di seberangnya, terlihat dari belakang, mengamati papan. Bidak merah dan putih sedang di tengah permainan, tetapi adegan ini kemungkinan diatur di studio. Foto stereo adegan rumah tangga semacam ini banyak dijual pada pertengahan abad ke-19."],"spots":[["Papan dan bidak","Bidak merah dan putih di papan berpetak."],["Tangan yang melangkah","Tangan wanita di sebuah bidak."],["Wanita","Bergaun kuning berkerah putih, menunduk ke papan."],["Pria","Duduk membelakangi kita."],["Tirai merah","Tirai berwarna di belakang."],["Gambar kedua","Pandangan kanan; dengan stereoskop pasangan ini tampak dalam."]]},"corrida":{"title":"Permainan Dadu Adu Banteng (Corrida de Toros)","artist":"José Guadalupe Posada","date":"1898","place":"Meksiko","game":"Permainan balap dua dadu dengan taruhan","medium":"Etsa timbul fotografis di atas kertas","size":"40,4 × 30,0 cm","credit":"","p":["Permainan balap bergambar karya Posada, berjudul “CORRIDA DE TOROS” (Adu banteng). Kotak-kotaknya berbentuk spiral dan menampilkan berurutan jurus serta momen adu banteng, dari kotak 1 di luar menuju tengah. Di tengah ada arena, dan di bawah tertera nama percetakan Antonio Vanegas Arroyo.","Menurut “Penjelasan” di bawah, dua orang atau lebih memasang taruhan lalu maju dengan melempar dua dadu. Angka 5, “lompat galah”, maju ke 10; 12, “pikador ditanduk”, membayar dan kehilangan giliran; 28, “umpan dada”, mulai lagi dari awal. Siapa yang mencapai 32, “banteng diseret keluar”, mengambil semua taruhan."],"spots":[["Judul","Tulisan “CORRIDA DE TOROS”."],["Arena","Bangunan arena di tengah spiral."],["Kotak 1","Awal permainan, di mulut spiral."],["Kepala banteng","Kepala banteng bertanduk di kanan atas."],["Matador","Potret seorang matador di kiri bawah."],["Penjelasan","“EXPLICACION” yang tercetak di bagian bawah."]]},"ambrocards":{"title":"Tiga Pria Bermain Kartu","artist":"Pembuat tak dikenal (Amerika)","date":"1865","place":"Amerika Serikat","game":"Kartu","medium":"Ambrotipe","size":"14,0 × 11,0 cm","credit":"","p":["Ambrotipe adalah negatif tipis di atas kaca yang dilapisi hitam di belakangnya sehingga tampak seperti positif. Lebih murah daripada dagerotipe, ia banyak dipakai di Amerika pada 1850–60-an. Yang ini berada di balik bingkai emas dalam kotak berlapis beledu merah.","Di depan latar polos, tiga pria mengelilingi meja kecil sambil memegang kartu. Yang kiri bertopi bundar dan yang kanan bertopi pet, keduanya mengisap cerutu; pria di tengah berjaket gelap menatap kita. Kemungkinan mereka berpose seolah sedang bermain untuk kamera."],"spots":[["Tangan","Tangan memegang kartu di atas meja."],["Pria bertopi bundar","Di kiri, dengan cerutu."],["Pria di tengah","Berjaket gelap, menatap kita."],["Pria bertopi pet","Di kanan, dengan cerutu."],["Bingkai emas","Bingkai emas bertimbul di sekeliling gambar."],["Kotak","Kotak berlapis beledu merah."]]},"morphy":{"title":"Paul Morphy, Juara Catur","artist":"Winslow Homer","date":"1859","place":"Amerika Serikat","game":"Catur","medium":"Ukiran kayu ujung","size":"","credit":"","p":["Potret ukiran kayu bertuliskan “PAUL MORPHY, THE CHESS CHAMPION”, menurut gambar Winslow Homer (1836–1910) yang saat itu ilustrator muda. Morphy (1837–1884) dari New Orleans berkeliling Eropa pada 1858–59, mengalahkan master terkemuka satu demi satu, dan pulang dengan nama besar.","Morphy muda duduk dengan tangan kiri di tepi papan, di samping raja, benteng, pion, dan bidak lain. Dibuat pada 1859 ketika ia pulang sebagai tokoh terkenal, cetakan ini kemungkinan dimuat sebagai ilustrasi di surat kabar atau majalah."],"spots":[["Bidak","Raja, benteng, pion, dan lainnya di papan."],["Tangan di papan","Tangan kirinya di tepi papan."],["Wajah Morphy","Sang juara yang baru lewat dua puluh tahun."],["Dasi kupu-kupu","Kerah yang rapi."],["Tangan di lutut","Tangan kanannya di atas lutut."],["Judul","“PAUL MORPHY, THE CHESS CHAMPION” di bawah."]]},"dutton":{"title":"Keluarga Dutton di Ruang Tamu Sherborne Park, Gloucestershire","artist":"Johann Zoffany","date":"sekitar 1772","place":"Inggris","game":"Kartu","medium":"Cat minyak di atas kanvas","size":"101,5 × 127,0 cm","credit":"","p":["Karya Johann Zoffany (1733–1810), pelukis kelahiran Jerman yang berkarier di Inggris. “Conversation piece”, potret keluarga yang santai, lahir di Inggris abad ke-18 dan sangat populer. Latarnya ruang tamu Sherborne Park di Gloucestershire.","Menurut museum, ayah dan putri, ibu dan putra sedang menimbang langkah berikutnya dalam permainan kartu. Keluarga ini baru kehilangan orang tercinta, sehingga orang tua memakai pakaian berkabung penuh berwarna hitam, dan anak-anak berkabung ringan dengan ungu muda, putih, dan abu-abu."],"spots":[["Meja kartu","Meja berlapis kain hijau dengan kartu."],["Sang ayah","Berbaju hitam, memegang kartu."],["Sang putri","Berbaju putih, memperhatikan kartunya."],["Sang putra","Berbaju abu-abu, memegang kartunya."],["Sang ibu","Bergaun berkabung hitam."],["Perapian","Perapian marmer dengan api menyala."]]},"whist":{"title":"Para Akademisi Natal: Permainan Gabungan Whist","artist":"James Bretherton (kemungkinan menurut H. W. Bunbury)","date":"1773","place":"Inggris","game":"Whist (kartu)","medium":"Etsa","size":"26,5 × 39,6 cm","credit":"","p":["Menurut museum, ini sindiran terhadap para akademisi Cambridge. Di kiri bawah tampaknya terbaca “H. W. Bunbury del. 1772” dan di kanan bawah “J. Bretherton f.”; terbit tahun 1773 dari sebuah toko di New Bond Street, London. Topi akademis tergantung di dinding.","Empat pria bermain kartu whist sambil saling mengernyitkan muka. Whist dimainkan oleh dua pasangan, jadi “permainan gabungan” di judulnya kemungkinan permainan kata. Di belakang, seseorang membuat isyarat mengejek dengan jari di atas kepala orang lain. Di dekat mereka ada dua pelayan dan dua anjing."],"spots":[["Kartu di meja","Kartu yang dimainkan di meja."],["Akademisi berwig","Sarjana berwig besar, kartu didekap di dada."],["Isyarat jari","Pria di belakang mengangkat jari di atas kepala orang lain."],["Pelayan wanita","Pelayan bertopi membawa baki."],["Topi akademis","Topi universitas tergantung di dinding."],["Anjing di kanan","Anjing kecil menggonggong di kanan bawah."]]},"hey":{"title":"Tiga Pria Bermain Catur","artist":"Paul Hey","date":"1877–1952","place":"Jerman","game":"Catur","medium":"Cetakan (kemungkinan etsa)","size":"19,3 × 26,0 cm","credit":"","p":["Cetakan karya pelukis dan ilustrator Jerman Paul Hey (1867–1952). Tiga pria tua membungkuk di atas satu papan catur; garis-garis halus yang bertumpuk melukiskan kerut dalam dan janggut putih mereka.","Seperti catatan museum, pria di kiri menopang dagu dengan tangan, dan pria di kanan memegang cerutu sambil menjulurkan tangan ke bidak. Di kiri meja ada dua cangkir kopi, sebuah gelas, dan sekotak korek api. Kemungkinan ini permainan di sebuah kafe."],"spots":[["Papan catur","Papan dan bidak di atas meja."],["Pria bertopang dagu","Berjanggut putih, tenggelam dalam pikiran."],["Pria di tengah","Mencondongkan badan, menjangkau bidak."],["Pria di kanan","Mengintip dari belakang."],["Tangan bercerutu","Cerutu terselip di antara jari."],["Kopi dan korek","Dua cangkir, gelas, dan kotak korek api di kiri."]]},"artful":{"title":"Kartu Licik, atau Satu Terlalu Banyak untuk Nenek. Hati Jadi Truf!","artist":"Anonim","date":"1852–1863","place":"Kemungkinan Britania","game":"Kartu","medium":"Foto stereo, diwarnai","size":"8,4 × 17,4 cm","credit":"","p":["Judul bahasa Inggrisnya “The artful card, or, one too many for granny. Hearts are trumps!”. Adegan lucu tentang mengakali nenek dengan kartu licik, dibuat menjadi sepasang foto stereo. Dari judul bahasa Inggrisnya, kemungkinan dibuat di Britania.","Di meja bundar, nenek dan seorang gadis kecil bermain kartu, sementara wanita muda bergaun hijau yang memegang kartunya dirangkul dari belakang oleh seorang pemuda. “Hati jadi truf” kemungkinan permainan kata antara jenis kartu dan cinta. Ruangan dengan alat pemintal dan lemari pecah belah tentu set studio."],"spots":[["Kartu si wanita muda","Kartu yang dipegang wanita bergaun hijau."],["Pemuda","Tangannya di bahu si wanita dari belakang."],["Nenek","Wanita tua berkerudung, menatap kartunya."],["Gadis kecil","Tersenyum sambil memainkan kartu."],["Meja","Meja bundar dengan kartu dan barang kecil."],["Lemari pecah belah","Lemari berkaca berisi piring dan cangkir."]]},"cezcards":{"title":"Studi untuk Para Pemain Kartu","artist":"Paul Cézanne","date":"1890–92","place":"Prancis","game":"Kartu","medium":"Cat air dengan grafit di atas kertas krem","size":"36,2 × 48,5 cm","credit":"","p":["Pada 1890-an, di Aix, Prancis selatan, Cézanne melukis beberapa gambar pria bermain kartu. Ini studi cat air untuk seri itu: seorang pria berkumis dan bertopi duduk di meja, memandangi kartunya.","Di atas garis grafit, sapuan tipis biru dan abu-abu menangkap lipatan jaket dan bobot tubuhnya. Sisi kanan dan ujung meja dibiarkan belum selesai; warna hanya ada di sekitar sosoknya. Konon modelnya adalah para pekerja setempat."],"spots":[["Wajah","Menunduk di bawah topi, memandangi kartu."],["Kartu","Kartu yang dipegang dengan dua tangan."],["Meja","Meja yang hanya digambar dengan pensil."],["Kursi","Sandaran kursi di kiri."],["Jaket","Lipatan yang dibangun dengan biru dan abu-abu."],["Bagian belum selesai","Di dekat kaki meja hanya tersisa garis."]]},"vuillardck":{"title":"Permainan Dam, dari Pemandangan dan Interior","artist":"Édouard Vuillard","date":"1899","place":"Prancis","game":"Dam","medium":"Litografi berwarna di atas kertas Cina gading keabuan","size":"36,9 × 28,5 cm","credit":"","p":["Lembar pertama Pemandangan dan Interior, album litografi berwarna karya pelukis Prancis Vuillard, diterbitkan pedagang seni Ambroise Vollard dan dicetak oleh pencetak litografi Auguste Clot.","Di ruangan yang penuh kertas dinding bermotif, seorang pria berjanggut duduk di depan papan dam, sementara seorang wanita bergaun kotak-kotak berdiri dengan tangan di dagu, memperhatikan. Sosok, kertas dinding, dan sofa melebur menjadi warna datar dan motif; hanya kotak hitam-putih papan yang tampak tegas."],"spots":[["Papan","Papan dam hitam-putih."],["Pria berjanggut","Duduk di depan papan."],["Wanita yang berdiri","Bergaun kotak-kotak, tangan di dagu."],["Kertas dinding","Penuh garis berpilin."],["Bantal berbunga","Kain bermotif di kiri bawah."],["Lampu","Bentuk lampu ramping di dekat dinding."]]},"cruikchess":{"title":"Permainan Catur","artist":"George Cruikshank, menurut Kapten Frederick Marryat","date":"1814","place":"Inggris","game":"Catur","medium":"Etsa diwarnai tangan","size":"23,8 × 34,5 cm","credit":"","p":["Cetakan karikaturis Inggris Cruikshank berdasarkan sketsa Marryat, perwira angkatan laut yang kemudian menjadi novelis, diterbitkan di London oleh Hannah Humphrey. Di bawahnya tertera judul “GAME of CHESS”.","Di meja berlilin, dua pria tua berhadapan di depan papan catur. Di belakang masing-masing berdiri seorang penonton: yang kiri menaruh jari di bibir minta diam, yang kanan mengintip papan lewat kacamata bergagang. Kemungkinan ini mengejek penonton yang tak bisa diam."],"spots":[["Papan","Papan catur dengan bidak hitam-putih."],["Lilin","Dua lilin yang menerangi papan."],["Pria yang minta diam","Penonton dengan jari di bibir."],["Pria berkacamata","Penonton yang mengintip lewat kacamata bergagang."],["Anjing tidur","Anjing yang tidur di bawah meja."],["Judul","“GAME of CHESS” di bawah."]]},"domino98":{"title":"Wanita dan Anak Bermain Domino di Meja","artist":"Seniman tak dikenal (Amerika)","date":"sekitar 1898","place":"Amerika Serikat","game":"Domino","medium":"Cetak albumen ditempel di kaca","size":"40,8 × 51,1 cm","credit":"","p":["Foto besar, kemungkinan dari studio di Amerika, diselesaikan dengan ditempel di kaca. Seorang wanita bergaun putih dan gadis kecil berambut ikal duduk berhadapan di meja kecil berhias bunga.","Batu domino tergeletak di meja, dan wanita itu sedang meletakkan satu. Si gadis bertopang dagu sambil menonton. Tirai, lemari berhias, dan lukisan di dinding kemungkinan adalah latar studio."],"spots":[["Batu domino","Batu domino putih di atas meja."],["Gadis kecil","Bertopang dagu memandangi batu."],["Wanita","Bergaun putih, meletakkan batu."],["Bunga","Vas bunga di meja."],["Lemari","Lemari berhias di kanan belakang."],["Tulisan","Huruf putih di kanan bawah."]]},"langkat":{"title":"Albert Glaser Bermain Kartu dengan Dua Kawan di Perahu, Langkat, Sumatra","artist":"Anonim (H. Ernst & Co.)","date":"1895–1905","place":"Indonesia (Langkat, Sumatra)","game":"Kartu","medium":"Foto","size":"17,5 × 22,8 cm","credit":"","p":["Foto yang diambil di Langkat, Sumatra bagian utara. Di kanan bawah ada cap timbul studio “H. Ernst & Co. / Bindjey Langkat”, dan di baliknya ada catatan tangan bahwa pria di tengah adalah Albert Glaser, saudara laki-laki seorang nyonya.","Di geladak perahu beratap peneduh, tiga pria berbaju putih duduk di meja sambil memegang kartu. Di meja ada kartu dan benda kecil mirip koin, dan sebuah botol di dekat pria di kanan. Baju putih dan atap peneduh menceritakan hidup di iklim panas."],"spots":[["Di atas meja","Kartu yang dibagikan dan benda mirip koin."],["Glaser","Pria di tengah membuka kartunya; catatan di balik foto menyebut namanya."],["Pria di kiri","Terlihat setengah dari belakang, memegang kartu."],["Pria di kanan","Berkumis, memegang kartu di meja."],["Botol","Botol di dekat pria di kanan."],["Atap peneduh","Hiasan daun yang menjuntai dari atap peneduh."]]},"chatur":{"title":"Sebuah Permainan Chaturanga","artist":"Anonim","date":"1805–1815","place":"India","game":"Chaturanga","medium":"Guas dan emas, kuas","size":"16,2 × 9,8 cm (gambar)","credit":"","p":["Sebuah lukisan miniatur India. Menurut catatan museum, dua wanita bermain chaturanga, sebuah permainan papan, sementara seorang pelayan memegang kebut lalat. Chaturanga adalah permainan papan India kuno yang dianggap leluhur catur.","Di bawah lengkungan putih, di atas permadani merah, wanita berbaju biru tua dan wanita berbaju jingga berhadapan di depan papan kotak-kotak. Wanita berbaju jingga mengulurkan tangan seperti sedang berbicara. Gambar dibingkai pinggiran merah tua bergaris hitam dan putih."],"spots":[["Papan","Papan kotak-kotak di atas permadani merah."],["Wanita berbaju biru","Berhias emas, menjangkau papan."],["Wanita berbaju jingga","Di hadapannya, tangan terulur."],["Pelayan","Berdiri di belakang."],["Kebut lalat","Diangkat oleh pelayan."],["Bingkai merah","Bingkai merah tua bergaris hitam dan putih."]]},"shabbarat":{"title":"Malam di Ruang Para Wanita","artist":"Anonim","date":"1760–1770","place":"India","game":"Chaupar (pachisi)","medium":"Guas dan emas, kuas","size":"34,3 × 25,6 cm","credit":"","p":["Sebuah lukisan miniatur India. Menurut catatan museum, empat wanita bermain permainan papan di halaman istana yang luas, permainan yang disebut chaupar atau pachisi. Mereka duduk mengelilingi papan kain berbentuk salib.","Wanita di depan kanan memegang tiga dadu panjang, siap melempar. Di sebelahnya, bersandar pada guling, adalah wanita berkedudukan tertinggi. Malam telah tiba, tetapi lampu menerangi teras di mana-mana dan cahaya tak terhitung berderet di tembok kota di kejauhan. Catatan menduga hari raya Islam Syab-e Barat sedang dirayakan."],"spots":[["Papan salib","Papan berbentuk salib yang terbentang di lantai."],["Wanita dengan dadu","Di depan, memegang dadu panjang."],["Wanita bersandar guling","Wanita berkedudukan tertinggi."],["Pelayan","Datang membawa baki."],["Lampu","Lilin di bawah tudung kaca."],["Paviliun di kejauhan","Taman berair mancur, paviliun, dan lampu kota."]]},"govase":{"title":"Vas Bulat Telur dengan Wanita Bermain Go","artist":"Anonim (cap “Tang Jintang”)","date":"1724","place":"Tiongkok (Guangdong)","game":"Go (weiqi)","medium":"Porselen dengan email di atas glasir dan sepuhan emas","size":"Tinggi 15,3 cm","credit":"","p":["Vas Tiongkok dari porselen yang sangat tipis, dilukis dengan email. Di baliknya tertulis “gambar sebuah permainan go, dilukis pada hari Festival Bunga tahun jiachen, di rumah nyaman di tepi Sungai Mutiara di Lingnan”, dengan cap merah “Tang Jintang”. Vas ini termasuk koleksi porselen kolektor Den Haag Jean Theodore Royer.","Dua wanita berhadapan di depan papan go di atas meja; yang kiri memegang mangkuk batu. Di kanan, dua wanita dan dua anak membungkuk menonton. Di rak belakang ada barang antik, di antaranya vas berisi bulu merak dan karang."],"spots":[["Papan","Papan go di meja, dengan batu hitam dan putih."],["Pemain kiri","Memegang mangkuk batu sambil menunjuk."],["Pemain kanan","Membungkuk ke papan."],["Para penonton","Wanita yang mengintip dari belakang."],["Bulu merak dan karang","Dalam vas di atas rak."],["Mangkuk batu","Di tangan wanita di kiri."]]},"yokihi":{"title":"Pria Bermain Backgammon dengan Seorang Wanita (Kaisar Xuanzong dan Yang Guifei)","artist":"Anonim (surimono)","date":"1822","place":"Jepang","game":"Ban-sugoroku (backgammon Jepang)","medium":"Cetak kayu berwarna dengan pigmen logam","size":"21,6 × 19,1 cm","credit":"","p":["Sebuah surimono, cetakan mewah yang memadukan gambar dan puisi, dicetak di kertas tebal dengan serbuk logam dan dipesan para penyair sebagai hadiah bagi kawan. Lembar ini memuat satu puisi dan nama penyair Tachibana no Goen.","Menurut catatan museum, Kaisar Tang Xuanzong (685–762) bermain sugoroku dengan selir kesayangannya Yang Guifei (719–756), permainan sekerabat backgammon dan trictrac. Di papan berbentuk kotak di atas dudukan merah berdiri bidak hitam dan putih."],"spots":[["Papan","Papan sugoroku berbentuk kotak di atas dudukan merah."],["Yang Guifei","Berhias bunga di rambut, tangannya di papan."],["Xuanzong","Bertopang dagu, memandangi papan."],["Puisi","Sebuah puisi dan nama penyair di kiri atas."],["Sekat lipat","Sekat bergambar pegunungan di belakang."],["Tanda tangan dan cap","Tanda tangan dan cap merah di kanan bawah."]]},"disderi":{"title":"Para Pria Berkostum Pelaut Bermain Kartu","artist":"Disdéri & Cie","date":"1850–1890","place":"Prancis (Paris)","game":"Kartu","medium":"Cetak albumen (carte de visite)","size":"8,6 × 5,3 cm","credit":"","p":["Foto berformat carte de visite dari sebuah album, di baliknya tercetak “Disdéri & Cie, 8 Boulevard des Italiens, Paris”. Disdéri adalah fotografer yang memopulerkan carte de visite, potret kecil yang dicetak banyak seperti kartu nama.","Para pria berpakaian kuno — topi tricorn, jas panjang, kaus kaki putih — bermain kartu mengelilingi meja bermotif. Catatan museum menyebutnya kostum pelaut, tetapi kemungkinan kostum sandiwara atau pesta topeng. Pria di tengah berdiri untuk melihat meja."],"spots":[["Meja","Meja berbingkai motif, dengan kartu dan cangkir."],["Pria yang berdiri","Bertopi tricorn, membungkuk ke meja."],["Pria di kiri","Duduk, memegang kartu."],["Pria di kanan","Bertopi tricorn, memegang kartu."],["Sepatu bergesper","Kaus kaki putih dan sepatu bergesper."],["Bingkai emas","Pinggiran emas pada karton."]]},"gans":{"title":"Permainan Angsa (Spiral 74 Kotak)","artist":"Jan Oortman (ayah), menurut rancangan Daniel Willem Stoopendaal","date":"1763–1823","place":"Belanda","game":"Permainan angsa (balap dadu)","medium":"Cetak kayu diwarnai biru, merah, dan hijau","size":"40,8 × 46,8 cm","credit":"","p":["Papan balap berbentuk spiral yang dicetak di Belanda. Menurut museum, kotaknya bernomor 1 sampai 74, sebagian bergambar. Jan Oortman menoreh klisenya menurut rancangan Stoopendaal, yang namanya tertera di kanan bawah dengan “invenit”.","Tujuan, nomor 74, adalah kuil di tepi laut saat matahari terbenam di tengah. Ada kotak bertuliskan “LEER GELD” (uang pelajaran), “DWAALWEG” (jalan sesat), “DOMHEID / WYSHEID” (kebodohan / kebijaksanaan), dan kerangka bersabit “EINDE” (akhir); kemungkinan ini permainan moral tentang jalan hidup."],"spots":[["74: kuil","Tujuan: kuil di tepi pantai saat senja."],["1: awal","Kotak pertama di kiri bawah."],["Uang pelajaran","Kotak “LEER GELD”, kemungkinan tempat membayar."],["Jalan sesat","Jalan hutan bertuliskan “DWAALWEG”."],["Akhir","Kerangka bersabit: “EINDE”."],["Dadu","Kotak bergambar dua dadu."]]},"merelle":{"title":"Merelle dan Layang-layang","artist":"Claudine Stella, menurut Jacques Stella","date":"1657","place":"Prancis (Paris)","game":"Merelle (nine men’s morris)","medium":"Gravir","size":"11,7 × 14,1 cm","credit":"","p":["Lembar ke-17 dari seri permainan anak yang digravir Claudine Stella menurut rancangan pamannya, pelukis Jacques Stella. Menurut museum, lembar ini berasal dari album berisi 51 gravir. Yang bermain adalah anak-anak telanjang yang montok, putti.","Di kiri depan mereka bermain merelle (nine men’s morris) di papan yang digores pada balok batu. Di tanah sebelah kanan ada garis permainan franc du carreau, melempar koin ke petak, dan agak jauh seorang anak berlari membawa layang-layang. Sajak di bawah mengatakan semua bersungguh-sungguh bermain."],"spots":[["Papan merelle","Papan yang dipahat di batu, dengan bidaknya."],["Layang-layang","Layang-layang tinggi di udara."],["Anak berlayang-layang","Berlari memegang benang."],["Franc du carreau","Kotak dan diagonal di tanah."],["Anak yang menunjuk","Memegang sesuatu, menunjuk garis."],["Judul","“LA MERELLE, & LE CERF VOLANT”."]]},"feldcards":{"title":"Bermain Kartu di Meja Taman (Foto Stereo)","artist":"Anonim","date":"1850–1880","place":"Tidak diketahui (cap perusahaan Groningen di balik foto)","game":"Kartu","medium":"Cetak albumen (foto stereo)","size":"8,5 × 17,0 cm","credit":"","p":["Foto stereo sebuah keluarga atau sekelompok kawan bermain kartu di meja taman, berlatar kisi-kisi yang dirambati tanaman. Di baliknya ada cap Feldbrugge & Co., Groningen (Belanda), kemungkinan toko atau penerbit yang menjualnya.","Pria berjanggut di kiri mengangkat kartu tinggi-tinggi, siap menghentakkannya ke meja. Pria yang menopang kepala dengan tangan, anak laki-laki dengan kartunya, kakek berambut putih, dan wanita yang menonton dari belakang melengkapi momen itu. Karena semua harus diam lama, adegan ini kemungkinan berpose."],"spots":[["Kartu yang diangkat","Kartu yang diacungkan pria berjanggut."],["Di atas meja","Kartu yang sudah dimainkan."],["Kartu si anak","Kartu anak laki-laki yang membelakangi kita."],["Kakek","Pria berambut putih yang duduk di kanan."],["Wanita yang menonton","Berdiri di belakang mengikuti permainan."],["Kursi bersulam","Kursi di depan berlapis kain bermotif bunga."]]},"tempel":{"title":"Papan Permainan “Kuil Keberuntungan”","artist":"Anonim","date":"1816","place":"Belanda","game":"Permainan balap dengan dadu","medium":"Cetak kayu dengan teks cetak timah","size":"43,0 × 48,5 cm","credit":"","p":["Lembar permainan dengan kotak 1 sampai 74 yang melingkar seperti spiral. Di tengah berdiri kuil bundar di tepi laut; lembar aturan yang tersimpan di koleksi yang sama menyebutnya “Kuil Keberuntungan” dan menyebut permainan lempar, yaitu permainan dadu.","Kebanyakan kotak berupa lingkaran kosong, tetapi di sana-sini ada gambar mawar, duri, dadu, gerbang besi, perahu tambang, dan lainnya, serta kata-kata seperti “LEER GELD” (uang belajar), “DOMHEID” (kebodohan), dan “WYSHEID” (kebijaksanaan). Kemungkinan ini permainan bermuatan moral yang melewati perbuatan baik dan buruk menuju kuil."],"spots":[["Kuil Keberuntungan","Kuil di tepi laut di tengah: kotak 74, tujuan."],["Kotak 1","Awal permainan di kiri bawah."],["Uang belajar","Kotak bertuliskan “LEER GELD”."],["Dadu","Dua dadu di baris atas."],["Perahu tambang","Gambar “OVER HAAL” (penyeberangan) di baris bawah."],["Kebodohan dan kebijaksanaan","Kata “DOMHEID” dan “WYSHEID” di kanan."]]},"verkeer":{"title":"Papan Verkeer Mini","artist":"Anonim","date":"1690–1710","place":"Belanda (Amsterdam)","game":"Verkeer (kerabat backgammon), catur, nine men’s morris","medium":"Kayu walnut bertatah kayu zaitun, eboni, boxwood, dan tulang; kelengkapan tembaga","size":"Tertutup 5,8 × 5,8 cm (terbuka 11,6 cm)","credit":"","p":["Papan permainan yang sisinya hanya sekitar enam sentimeter dan terbuka seperti kotak. Di luar ada papan catur dan papan nine men’s morris; di dalam ada papan verkeer, kerabat backgammon dari Belanda. Ditutup dengan engsel tembaga dan kait kecil.","Di dalamnya masih ada satu dadu, sembilan bidak tulang, empat bidak eboni, dan tiga koin kecil. Nomor museumnya menunjukkan bahwa ini kemungkinan bagian dari perabot rumah boneka Petronella Oortman. Meski mungil, tatahan kayunya teliti dan dibuat seperti papan sungguhan."],"spots":[["Dadu","Dadu sebesar butir beras."],["Bidak tulang","Bidak bundar dari tulang putih."],["Bidak eboni","Bidak hitam dari kayu eboni."],["Segitiga","Segitiga bertatah kayu terang dan gelap."],["Engsel","Engsel tembaga untuk melipat."],["Kait","Kait tembaga kecil untuk menutup."]]},"silverbd":{"title":"Papan Permainan Perak Mini dengan Bidak","artist":"Frederik van Strant II","date":"1739","place":"Belanda (Amsterdam)","game":"Dam, nine men’s morris","medium":"Perak","size":"5,4 × 5,4 cm","credit":"","p":["Papan perak yang sisinya hanya 5,4 sentimeter: 64 kotak, tepi yang ditinggikan, dan cincin untuk menggantung. Kotak gelap diukir garis halus, dan sisi lainnya diukir garis untuk nine men’s morris.","Papan ini bercap kota Amsterdam, huruf tahun E untuk 1739, dan cap pandai perak Frederik van Strant II. Lima belas bidak dam masih menyertainya, delapan bermotif bunga dan tujuh bermotif lingkaran. Kemungkinan ini miniatur perak untuk rumah boneka atau lemari pajangan."],"spots":[["Bidak bunga","Bidak bercap bunga."],["Bidak lingkaran","Bidak bertanda lingkaran."],["Cincin","Cincin di sudut papan."],["Kotak berukir","Kotak gelap bergaris halus."],["Kotak polos","Kotak terang yang halus dan mengilap."],["Tepi","Tepi yang ditinggikan di sekeliling papan."]]},"schaak1550":{"title":"Set Catur dengan Bidak Berkuda","artist":"Anonim","date":"1550","place":"Jerman","game":"Catur","medium":"Kayu boxwood dan kayu jarum","size":"Bidak terbesar tinggi 10,5 cm","credit":"","p":["Setiap bidak berdiri di atas alas bubutan yang dikelilingi pagar hiasan bunga, dengan ukiran penunggang dan kuda. Raja dan ratu menunggang kuda atau bagal, seolah hendak berburu.","Menurut catatan museum, raja hitam menunggang kuda berdiri yang menginjak naga dan memakai rantai yang mengingatkan pada Ordo Bulu Domba Emas, mungkin menandainya sebagai Karel V. Seorang ratu duduk menyamping di atas bagal dengan elang di tangannya. Di paling kanan ada bidak jenaka: seekor monyet menunggang punggung orang."],"spots":[["Raja","Raja bermahkota dan berjanggut di atas kuda."],["Ratu","Ratu duduk menyamping di atas bagal, membawa elang."],["Bidak monyet","Monyet di punggung seorang pria."],["Bidak jenaka","Di paling kiri, orang menunggang orang."],["Makhluk di bawah kaki","Naga dan binatang di bawah kuku kuda."],["Alas","Alas bubutan berpagar hiasan bunga."]]},"kraaij":{"title":"Pria dan Wanita Bermain Permainan Papan di Ruang Keluarga","artist":"Anonim","date":"1900–1910","place":"Kemungkinan Belanda","game":"Backgammon","medium":"Cetak kolodion cetak-langsung","size":"8,0 × 11,1 cm","credit":"","p":["Satu halaman dari album keluarga yang juga memuat foto pedagang anggur Kraaij & Co., Bordeaux–Amsterdam. Di ruang keluarga berlampu gantung, para pria dan wanita, mungkin keluarga dan kawan, duduk mengelilingi meja.","Di meja terbuka papan berbentuk kotak lipat, dan wanita di kedua sisi masing-masing memegang gelas dadu. Catatan museum menyebut “permainan papan”, tetapi dari kotak dan gelasnya kemungkinan ini backgammon. Cangkir kopi di dekatnya dan sangkar burung di belakang memberi suasana malam santai di rumah."],"spots":[["Papan kotak","Kotak lipat yang dibuka menjadi papan."],["Gelas dadu kiri","Gelas wanita berkacamata."],["Gelas dadu kanan","Wanita bergaun bintik siap melempar."],["Sangkar burung","Sangkar di atas tatakan di belakang."],["Lampu gantung","Lampu bertudung kaca yang tergantung dari langit-langit."],["Pria yang berdiri","Di kanan, menonton permainan."]]},"braekel":{"title":"Kakek dan Nenek Bermain Dam","artist":"Ferdinand De Braekeleer (I)","date":"1862","place":"Belgia (Antwerpen)","game":"Dam (checkers)","medium":"Etsa","size":"21,8 × 16,5 cm","credit":"","p":["Etsa karya pelukis Antwerpen De Braekeleer (1792–1883), bertanda tangan di kiri bawah “Ferdinand De Braekeleer Antwerpen 1862”. Di dapur tua berperapian, seorang kakek dan nenek duduk berhadapan di meja kecil.","Bidak-bidak bundar ada di papan; si kakek mengambil satu sementara si nenek membuka tangan seolah membantah. Di lantai ada topi dan beberapa bidak yang jatuh. Rak berisi piring, dan dari jendela tampak rumah-rumah."],"spots":[["Papan dan bidak","Papan dan bidak bundar di meja."],["Si kakek","Membungkuk mengambil bidak."],["Si nenek","Berkerudung, berbicara sambil bergerak tangan."],["Topi di lantai","Topi si kakek di lantai."],["Tanda tangan","“Ferdinand De Braekeleer Antwerpen 1862”."],["Piring di rak","Piring besar di rak atas perapian."]]},"billiard":{"title":"Biliar","artist":"Menurut H. W. Bunbury (pencetak tak dikenal)","date":"1780","place":"Inggris (London)","game":"Biliar","medium":"Etsa dan teknik titik","size":"30,0 × 39,1 cm","credit":"","p":["Cetakan menurut gambar karikaturis Inggris Henry William Bunbury, diterbitkan di London tahun 1780 oleh Watson & Dickinson. Menurut museum, ini nomor empat dari satu seri.","Dua pria bermain biliar sementara yang lain menonton sambil menahan napas. Seorang membungkuk di atas meja untuk menyodok; yang lain memanggul stiknya. Di dinding ada rak stik dan dua piringan bundar penghitung skor. Museum mencatat bahwa mejanya tampak berbentuk segitiga."],"spots":[["Meja dan bola","Meja berlapis kain dan bolanya."],["Yang membidik","Membungkuk di atas meja untuk menyodok."],["Pria berstik","Menunggu dengan stik panjangnya."],["Piringan skor","Dua piringan di dinding, kemungkinan untuk menghitung skor."],["Rak stik","Sederet stik di dinding."],["Dua yang tertawa","Dua penonton di kanan tertawa bersama."]]},"baizi":{"title":"Seratus Anak (detail)","artist":"Xu Yanghong","date":"Abad ke-18","place":"Tiongkok","game":"Weiqi (go)","medium":"Gulungan mendatar; tinta (dan warna tipis) di atas kertas","size":"29,8 × 526 cm (seluruh gulungan)","credit":"","p":["Adegan go yang dipotong dari gulungan sepanjang lebih dari lima meter karya pelukis profesional Tiongkok Xu Yanghong. Di sebuah taman, seratus anak bermain, bermusik, membaca, dan menulis. “Seratus anak” adalah tema penting seni Asia yang melambangkan banyak keturunan dan keluarga yang makmur.","Gulungan ini juga dikenal lewat salinan kemudian oleh maestro Jepang Tani Bunchō, yang ada di museum yang sama. Di dekat daun pisang dan batu hias, anak-anak mengelilingi papan go di atas dudukan rendah; dua bermain sambil memegang mangkuk batu, yang lain mengintip."],"spots":[["Papan","Papan go di atas dudukan rendah, dengan batu."],["Anak yang melangkah","Berjaket biru, tangan di mangkuk batu."],["Pemain lainnya","Berbaju putih, membungkuk ke papan."],["Tangan di belakang kepala","Anak yang menonton dari belakang."],["Batu hias","Batu besar penuh lubang."],["Kipas bulu","Anak di kiri memegang kipas bulu."]]},"schenkcards":{"title":"Dua Wanita Tiongkok Bermain Kartu","artist":"Pieter Schenk (II)","date":"1727–1775","place":"Belanda (subjek: Tiongkok)","game":"Kartu","medium":"Etsa","size":"16,5 × 26,2 cm","credit":"","p":["Selembar dari bagian pertama “Orang-orang Tiongkok Rekaan Baru”, album figur dan pemandangan bergaya Tiongkok terbitan pengukir dan penerbit Amsterdam Pieter Schenk Muda. Ini chinoiserie, selera akan Tiongkok khayalan yang sedang digemari di Eropa.","Menurut catatan museum, dua wanita Tiongkok bermain kartu di taman, sementara seorang wanita datang dari kanan membawa baki penuh. Kartu di meja tampak seperti kartu remi Eropa. Di kiri seekor kelinci beristirahat di atas dudukan, dan di sungai ada perahu layar."],"spots":[["Kartu di meja","Kartu terhampar di meja; tampak seperti kartu Eropa."],["Wanita di kiri","Memegang kartu, menatap lawannya."],["Wanita di kanan","Meletakkan kartu di meja."],["Wanita membawa baki","Membawa baki berisi makanan."],["Kelinci","Beristirahat di dudukan di kiri."],["Perahu layar","Perahu di sungai."]]},"gosaucer":{"title":"Piring Tatakan dengan Orang Bermain Go","artist":"Anonim","date":"1725–1735","place":"Tiongkok","game":"Go (weiqi)","medium":"Porselen dengan email di atas glasir dan sepuhan emas","size":"Diameter 16,4 cm","credit":"","p":["Piring tatakan Tiongkok yang dilukis dengan warna lembut di atas glasir yang disebut famille rose. Di bagian bawah ada tanda kuas, tongkat ruyi, dan batang tinta dalam lingkaran ganda. Catatan museum menyebut tokohnya kadang seorang pria dan wanita bermain go, kadang tiga wanita yang dua di antaranya bermain.","Di sebuah ruangan ada papan go di meja; dua pemain berhadapan meletakkan batu, dan orang ketiga berdiri menonton di belakang. Di meja ada mangkuk batu kuning; di belakang rak dengan vas bunga, dan di kanan guci biru besar."],"spots":[["Papan","Papan go dengan batu di meja."],["Pemain kiri","Berbaju ungu muda, bersandar ke meja."],["Pemain kanan","Berbaju merah muda, meletakkan batu."],["Penonton","Berdiri di belakang menonton."],["Vas","Vas bunga di atas rak."],["Guci biru","Guci besar di kanan."]]},"cheetham":{"title":"Pesta Kartu Kecil (di Rusia)","artist":"Anonim","date":"1903–1904","place":"Rusia","game":"Kartu","medium":"Cetak gelatin perak cetak-langsung","size":"9,2 × 11,5 cm","credit":"","p":["Dari album keluarga Inggris Cheetham yang tinggal di Rusia; di kartonnya tertulis dalam bahasa Inggris “a little card-party”. Museum mencatat bahwa mereka kemungkinan teman-teman Inggris yang mengunjungi Joseph Cheetham.","Di ruangan berkertas dinding, tiga orang duduk di meja bertaplak bunga dengan kartu terbuka di tangan. Dua kandil berdiri di meja, dan wanita di tengah tertawa sambil membuka kartunya seperti kipas. Kemungkinan ini saat santai bersama kawan sekampung di negeri yang jauh."],"spots":[["Kartu pria kiri","Kartu pria berjanggut."],["Kartu si wanita","Wanita di tengah membuka kartu seperti kipas."],["Pria di kanan","Condong ke depan, memegang kartu."],["Kandil","Dua kandil di meja."],["Taplak","Taplak besar bermotif bunga."],["Tulisan","“a little card-party” di karton."]]},"problem":{"title":"Teka-teki (Foto Stereo)","artist":"Anonim","date":"1852–1863","place":"Tidak diketahui","game":"Catur","medium":"Foto stereo, diwarnai","size":"8,4 × 17,4 cm","credit":"","p":["Judul bahasa Inggrisnya “The Problem”. Dua sosok berwig putih dan berpakaian gaya abad ke-18 bermain catur di meja berukir, dalam sepasang foto stereo yang diwarnai. Di baliknya tertulis tangan “Simons”.","Yang lebih muda memegang kedua pipinya dan menatap papan, sementara pria tua di seberangnya menyeringai. Kemungkinan ini adegan teatrikal yang diatur, di mana sekilas terlihat siapa yang punya masalah. Seekor anjing berbaring di kaki mereka."],"spots":[["Papan dan bidak","Papan dan bidak di meja berukir."],["Pemain yang bingung","Menopang kepala dengan dua tangan, menatap papan."],["Pria yang menyeringai","Pria tua berjas biru tersenyum."],["Anjing","Anjing yang berbaring di kaki mereka."],["Tirai merah","Tirai berwarna di belakang."],["Gambar kedua","Pandangan kanan; dengan stereoskop tampak dalam."]]},"tarocco":{"title":"Sepuluh Kartu dari Satu Set Tarot","artist":"Anonim (kemungkinan menurut Giuseppe Maria Mitelli)","date":"1660–1718","place":"Italia (Bologna)","game":"Tarocchi (permainan kartu dengan truf)","medium":"Etsa dan gravir, sebagian diwarnai tangan cokelat muda","size":"Sepuluh kartu di atas karton","credit":"","p":["Sepuluh kartu dari satu set tarot buatan Bologna, ditempel berdampingan di atas karton. Tarot mula-mula tidak dipakai untuk meramal, melainkan untuk permainan kartu dengan truf. Di kiri atas ada kartu judul; museum menduga potretnya mungkin seniman Mitelli.","Baris atas menampilkan empat sosok, di antaranya pria bermahkota dan penunggang kuda; baris bawah memuat enam sampai sepuluh dari jenis koin, masing-masing dengan koin sebanyak angkanya. Garis cetaknya sebagian diberi warna cokelat muda."],"spots":[["Kartu judul","Kiri atas: potret berbingkai dan tulisan."],["Pria bermahkota","Sosok bermahkota memegang tongkat kerajaan."],["Wanita berdiri","Wanita bermahkota memegang cawan."],["Penunggang kuda","Kartu dengan sosok di atas kuda."],["Sepuluh koin","Kiri bawah: sepuluh koin."],["Enam koin","Kanan bawah: enam koin."]]},"kindtegel":{"title":"Ubin dengan Adegan Anak-anak Bermain","artist":"Anonim","date":"1680–1730","place":"Belanda","game":"Permainan anak (egrang, ayunan, dan lainnya)","medium":"Gerabah berglasir timah (ubin Delft), dilukis biru","size":"107 × 80 cm (48 ubin)","credit":"","p":["Satu bidang berisi empat puluh delapan ubin, delapan ke atas dan enam ke samping. Tiap ubin menampilkan dua anak bermain yang dilukis kecil dengan warna biru, dengan hiasan kecil bernama “laba-laba” di setiap sudut.","Ada yang berjalan dengan egrang, ada yang didorong di ayunan, ada yang berjongkok memainkan sesuatu di tanah: tiap ubin menampilkan permainan yang berbeda. Ubin “permainan anak” seperti ini digemari di Belanda dan kemungkinan dipasang di dinding dapur dan sekitar perapian."],"spots":[["Egrang","Anak yang berjalan dengan egrang."],["Ayunan","Anak yang didorong di ayunan."],["Permainan di tanah","Anak-anak berjongkok bermain dengan sesuatu di tanah."],["Hiasan laba-laba","Hiasan kecil di sudut ubin."],["Empat puluh delapan ubin","Delapan baris berisi enam ubin."],["Ubin terakhir","Ubin di sudut kanan bawah."]]},"dammolen":{"title":"Papan Mini untuk Dam dan Morris","artist":"Anonim","date":"1740–1760","place":"Belanda (Amsterdam)","game":"Dam, nine men’s morris","medium":"Kayu walnut dengan pasta pengisi terang","size":"4,2 × 4,0 × 1,5 cm","credit":"","p":["Papan kayu walnut mungil selebar sekitar empat sentimeter. Hampir persegi dan bertepi tinggi, satu sisinya dipakai sebagai papan dam dan sisi lainnya sebagai papan morris.","Di sisi dam, kotak-kotak dicungkil lalu diisi pasta terang sehingga membentuk pola papan catur dengan warna kayu; di sisi morris, garis-garis yang dicungkil juga diisi pasta yang sama. Karena begitu kecil, kemungkinan dibuat untuk rumah boneka."],"spots":[["Kotak berisi pasta","Kotak dicungkil dan diisi pasta terang."],["Kotak kayu","Kotak berwarna kayu walnut asli."],["Tepi","Tepi yang ditinggikan di sekeliling."],["Sudut depan","Sudut yang paling dekat."],["Ketebalan","Sisi papan setinggi 1,5 cm."],["Baris belakang","Baris kotak paling belakang."]]},"karelpiece":{"title":"Bidak Dam dengan Potret Karel Agung (separuh)","artist":"Anonim","date":"1525–1575","place":"Jerman (Nuremberg)","game":"Dam atau backgammon","medium":"Kayu boxwood","size":"Diameter 5,3 cm","credit":"","p":["Satu sisi bidak dam berukir dari kayu boxwood. Di tengah ada wajah tampak samping berbingkai karangan daun salam, dan di sekelilingnya tulisan “CAROLVS. MAGNVS. IMPER. AVGVST.” (Kaisar Karel Agung).","Museum menyimpan lebih dari selusin bidak buatan serupa, masing-masing berukir kaisar atau permaisuri dari Romawi kuno hingga Abad Pertengahan: Tiberius, Agrippina, Louis yang Saleh, Otto, dan lainnya. Kemungkinan ini set mewah yang dirancang sebagai galeri para penguasa."],"spots":[["Wajah samping","Wajah Karel Agung dalam karangan daun salam."],["Karangan","Lingkaran daun salam di sekeliling potret."],["CAROLVS","Tulisan “CAROLVS. MAGNVS” di atas."],["AVGVST","Tulisan “IMPER. AVGVST” di kiri."],["Bintang","Bintang kecil pemisah tulisan."],["Tepi","Tepi bidak yang bertingkat."]]}};
